local BattlePermissions = {};

-- Services --
local ReplicatedStorage = game:GetService("ReplicatedStorage");
local ServerStorage = game:GetService("ServerStorage");
local TextService = game:GetService("TextService");
local Players = game:GetService("Players");

-- Main Variables --
local RankedPlayers = {}; -- [player] = "rankName"
local ActiveInvites = {}; -- [player] = "lineOwnerName"

-- Remotes --
local Remotes = ReplicatedStorage:WaitForChild("Remotes");
local EventToClient = Remotes:WaitForChild("EventToClient");

-- Local Functions --
local function GetFilteredMessage(text, playerID)
	local textObject;
	local filteredMessage;

	local success, errorMessage = pcall(function()
		textObject = TextService:FilterStringAsync(text, playerID);
		filteredMessage = textObject:GetNonChatStringForBroadcastAsync();
	end)

	if not success then
		print("Error generating TextFilterResult:"..errorMessage);
	end
	return filteredMessage;
end
local function SetPermissions(executorName, playerToGetRank, rank)
	RankedPlayers[playerToGetRank] = rank ~= "None" and rank or nil;
	EventToClient:FireAllClients("NotifyPermissions", {executorName, playerToGetRank.Name, rank});
	if not RankedPlayers[playerToGetRank] then
		BattlePermissions:DeleteLine(playerToGetRank);
	end
	return "Set the permissions for "..playerToGetRank.Name.." to "..rank..".";
end
local function UpdateLineInfo(lineID, attribute, value)
	for each, player in pairs(Players:GetPlayers()) do
		if player:GetAttribute("LineID") == lineID then
			player:SetAttribute(attribute, value);
			BattlePermissions:UpdatePlayerIcon(player);
		end
	end
end
local function GetLineAccessWithID(lineID)
	for each, player in pairs(Players:GetPlayers()) do
		if player:GetAttribute("LineID") == lineID then
			return player:GetAttribute("LineAccess");
		end
	end
end
local function GetLineOwnerWithID(lineID)
	for each, player in pairs(Players:GetPlayers()) do
		if player:GetAttribute("LineID") == lineID then
			return Players:FindFirstChild(player:GetAttribute("LineOwnerName"));
		end
	end
end
local function AddPlayerToLine(playerToAdd, lineOwner)
	playerToAdd:SetAttribute("LineID", lineOwner:GetAttribute("LineID"));
	playerToAdd:SetAttribute("LineName", lineOwner:GetAttribute("LineName"));
	playerToAdd:SetAttribute("LineIcon", lineOwner:GetAttribute("LineIcon"));
	playerToAdd:SetAttribute("LineOwnerName", lineOwner:GetAttribute("LineOwnerName"));
	playerToAdd:SetAttribute("LineTeamName", lineOwner:GetAttribute("LineTeamName"));
	playerToAdd:SetAttribute("LineAccess", lineOwner:GetAttribute("LineAccess"));
	BattlePermissions:UpdatePlayerIcon(playerToAdd);
end
local function RemovePlayerFromLine(playerToRemove, playerRemoving, lineCleared)
	if playerToRemove:GetAttribute("LineOwnerName") == playerToRemove.Name and not lineCleared then
		if playerRemoving then
			if playerToRemove == playerRemoving then
				BattlePermissions:DeleteLine(playerToRemove);
			end
		else
			BattlePermissions:DeleteLine(playerToRemove);
		end
	elseif playerRemoving then
		if playerToRemove:GetAttribute("LineID") == playerRemoving:GetAttribute("LineID") then
			playerToRemove:SetAttribute("LineID", BattlePermissions:GetPublicLineID());
			playerToRemove:SetAttribute("LineName", nil);
			playerToRemove:SetAttribute("LineIcon", nil);
			playerToRemove:SetAttribute("LineOwnerName", nil);
			playerToRemove:SetAttribute("LineTeamName", nil);
			playerToRemove:SetAttribute("LineAccess", nil);
		end
	else
		playerToRemove:SetAttribute("LineID", BattlePermissions:GetPublicLineID());
		playerToRemove:SetAttribute("LineName", nil);
		playerToRemove:SetAttribute("LineIcon", nil);
		playerToRemove:SetAttribute("LineOwnerName", nil);
		playerToRemove:SetAttribute("LineTeamName", nil);
		playerToRemove:SetAttribute("LineAccess", nil);
	end
	BattlePermissions:UpdatePlayerIcon(playerToRemove);
end

-- Module Functions --
function BattlePermissions:GetPlayerRank(player)
	return RankedPlayers[player];
end
function BattlePermissions:UpdatePlayerIcon(player)
	local character = player.Character;
	local head = character and character:FindFirstChild("Head");
	local icon = head and head:FindFirstChild("Icon");
	if icon then
		icon.Team.Image = player:GetAttribute("LineIcon") or ReplicatedStorage:GetAttribute(player.Team.Name.."Icon");
		icon.Backup.Image = ReplicatedStorage:GetAttribute(player.Team.Name.."Icon");
	end
end
function BattlePermissions:SetPlayerPermissions(executorName, playerToGetRank, rank)
	local currentRank = RankedPlayers[playerToGetRank];
	if not currentRank then
		return SetPermissions(executorName, playerToGetRank, rank);
	elseif currentRank ~= rank then
		return SetPermissions(executorName, playerToGetRank, rank);
	end
	return "Unable to change permissions, this player already has those permissions.";
end
function BattlePermissions:GetPlayerPermissions(player)
	return RankedPlayers[player];
end
function BattlePermissions:LineHasFlagActive(lineID)
	if lineID == BattlePermissions:GetPublicLineID() then
		return false;
	end

	for each, player in pairs(Players:GetChildren()) do
		for each, tool in pairs(player.Backpack:GetChildren()) do
			if tool.Name == "Flag" and tool:GetAttribute("LastLineID") == lineID then
				return true;
			end
		end
	end
	for each, character in pairs(workspace:GetChildren()) do
		if character:FindFirstChild("Humanoid") and character:FindFirstChild("Flag") then
			local player = Players:GetPlayerFromCharacter(character);
			if character.Flag:GetAttribute("LastLineID") == lineID then
				return true;
			end
		end
	end
	for each, droppedFlag in pairs(workspace.Flags:GetChildren()) do
		if droppedFlag:GetAttribute("LastLineID") == lineID then
			return true;
		end
	end
end
function BattlePermissions:CreateLine(player)
	if player:GetAttribute("LineID") == BattlePermissions:GetPublicLineID() then
		player:SetAttribute("LineID", BattlePermissions:GetLineIDFromPlayerID(player.UserId));
		player:SetAttribute("LineName", player.Name.."'s Line");
		player:SetAttribute("LineIcon", ReplicatedStorage:GetAttribute(player.Team.Name.."Icon"));
		player:SetAttribute("LineTeamName", player.Team.Name);
		player:SetAttribute("LineOwnerName", player.Name);
		player:SetAttribute("LineAccess", "Private");
		BattlePermissions:EnsureOnlyOneFlagInLine(player:GetAttribute("LineID"));
		return true;
	end
	return "Already in a line";
end
function BattlePermissions:DeleteLine(lineOwner)
	if lineOwner:GetAttribute("LineID") ~= BattlePermissions:GetPublicLineID() then
		if lineOwner:GetAttribute("LineOwnerName") == lineOwner.Name then
			BattlePermissions:RemoveAllFlagsFromLine(lineOwner:GetAttribute("LineID"))

			for each, otherPlayer in pairs(Players:GetPlayers()) do
				if otherPlayer:GetAttribute("LineOwnerName") ~= lineOwner.Name and otherPlayer:GetAttribute("LineID") == lineOwner:GetAttribute("LineID") then
					RemovePlayerFromLine(otherPlayer, nil, false);
				end
			end
			RemovePlayerFromLine(lineOwner, nil, true);

			return true;
		end
		return "Not line owner";
	end
	return "Line already deleted";
end
function BattlePermissions:UpdateLine(player, newName, newIcon)
	if player:GetAttribute("LineID") == BattlePermissions:GetLineIDFromPlayerID(player.UserId) then
		if newName then
			local filteredName = GetFilteredMessage(newName, player.UserId);
			if filteredName then
				if #filteredName > 0 and #filteredName <= 35 then
					UpdateLineInfo(BattlePermissions:GetLineIDFromPlayerID(player.UserId), "LineName", filteredName);
					return true;
				end
				return "Invalid name length";
			end
			return "Failed text filtering";
		elseif newIcon then
			local filteredIcon = tonumber(newIcon);
			if filteredIcon and filteredIcon >= 0 then
				if filteredIcon == 0 then
					filteredIcon = ReplicatedStorage:GetAttribute(player.Team.Name.."Icon");
				else
					filteredIcon = "rbxassetid://"..filteredIcon;
				end
				UpdateLineInfo(BattlePermissions:GetLineIDFromPlayerID(player.UserId), "LineIcon", filteredIcon);
				return true;
			end
			return "Invalid asset ID";
		end
		return "Invalid line data";
	end
	return "Line not created";
end
function BattlePermissions:JoinPublicLine(player, lineString)
	local lineID = tonumber(lineString);
	if player:GetAttribute("LineID") == BattlePermissions:GetPublicLineID() then
		local access = GetLineAccessWithID(lineID);
		if access then
			if access == "Public" then
				local lineOwner = GetLineOwnerWithID(lineID);
				if lineOwner then
					if lineOwner.Team == player.Team then
						if lineOwner ~= player then
							if player:GetAttribute("Loadout") == "Flag Bearer" and BattlePermissions:LineHasFlag(lineID) then
								return "Line already has flag";
							end

							AddPlayerToLine(player, lineOwner);
							return true;
						end
						return "Already in line";
					end
					return "Wrong team";
				end
				return "Line owner not found";
			end
			return "Line not public";
		end
		return "Line not found";
	end
	return "Already in line";
end
function BattlePermissions:LineHasFlag(lineID)
	for each, droppedFlag in pairs(workspace.Flags:GetChildren()) do
		if droppedFlag:GetAttribute("LastLineID") == lineID then
			return true;
		end
	end

	for each, player in pairs(Players:GetPlayers()) do
		if player:GetAttribute("LineID") == lineID then
			for each, tool in pairs(player.Backpack:GetChildren()) do
				if tool.Name == "Flag" then
					return true;
				end
			end
			if player.Character:FindFirstChild("Flag") then
				return true;
			end
		end
	end
end
function BattlePermissions:DropAllFlagsInLine(lineOwner)
	if lineOwner:GetAttribute("LineID") == BattlePermissions:GetLineIDFromPlayerID(lineOwner.UserId) then
		for each, character in pairs(workspace:GetChildren()) do
			if character:FindFirstChild("Humanoid") and character:FindFirstChild("Flag") then
				local player = Players:GetPlayerFromCharacter(character);
				if player and player ~= lineOwner and player.Team == lineOwner.Team and character.Flag:GetAttribute("LastLineID") == lineOwner:GetAttribute("LineID") then
					character.Humanoid:UnequipTools();
				end
			end
		end
		return true;
	end
	return "Line not created";
end
function BattlePermissions:EnsureOnlyOneFlagInLine(lineID)
	local flagActive = false;

	for each, player in pairs(Players:GetChildren()) do
		if player:GetAttribute("LineID") == lineID then
			for each, tool in pairs(player.Backpack:GetChildren()) do
				if tool.Name == "Flag" then
					if not flagActive then
						flagActive = true;
						tool:SetAttribute("LastLineID", lineID);
					else
						tool:Destroy();
					end
				end
			end
		end
	end
	for each, character in pairs(workspace:GetChildren()) do
		if character:FindFirstChild("Flag") then
			local player = Players:GetPlayerFromCharacter(character);
			if player:GetAttribute("LineID") == lineID then
				if not flagActive then
					flagActive = true;
					character.Flag:SetAttribute("LastLineID", lineID);
				else
					character.Flag:Destroy();
				end
			end
		end
	end
	for each, droppedFlag in pairs(workspace.Flags:GetChildren()) do
		if droppedFlag:GetAttribute("LastLineID") == lineID then
			if not flagActive then
				flagActive = true;
				droppedFlag:SetAttribute("LastLineID", lineID);
			else
				droppedFlag:Destroy();
			end
		end
	end

	return flagActive;
end
function BattlePermissions:RemoveAllFlagsFromLine(lineID)
	for each, player in pairs(Players:GetChildren()) do
		for each, tool in pairs(player.Backpack:GetChildren()) do
			if tool.Name == "Flag" and tool:GetAttribute("LastLineID") == lineID then
				tool:SetAttribute("LastLineID", BattlePermissions:GetPublicLineID());
			end
		end
	end
	for each, character in pairs(workspace:GetChildren()) do
		if character:FindFirstChild("Humanoid") and character:FindFirstChild("Flag") then
			local player = Players:GetPlayerFromCharacter(character);
			if character.Flag:GetAttribute("LastLineID") == lineID then
				character.Flag:SetAttribute("LastLineID", BattlePermissions:GetPublicLineID());
			end
		end
	end
	for each, droppedFlag in pairs(workspace.Flags:GetChildren()) do
		if droppedFlag:GetAttribute("LastLineID") == lineID then
			droppedFlag:SetAttribute("LastLineID", BattlePermissions:GetPublicLineID());
		end
	end
end
function BattlePermissions:UpdateLineAccess(access, lineOwner)
	if lineOwner:GetAttribute("LineID") == BattlePermissions:GetLineIDFromPlayerID(lineOwner.UserId) then
		if lineOwner:GetAttribute("LineAccess") ~= access then
			for each, player in pairs(Players:GetPlayers()) do
				if player:GetAttribute("LineID") == lineOwner:GetAttribute("LineID") then
					player:SetAttribute("LineAccess", access);
				end
			end
			return true;
		end
		return "Line already "..access;
	end
	return "Line not created";
end
function BattlePermissions:InvitePlayerToLine(playerNameToInvite, lineOwner)
	if lineOwner:GetAttribute("LineID") == BattlePermissions:GetLineIDFromPlayerID(lineOwner.UserId) then
		local playerToInvite = Players:FindFirstChild(playerNameToInvite);
		if playerToInvite then
			if playerToInvite:GetAttribute("LineID") == BattlePermissions:GetPublicLineID() then
				if not ActiveInvites[playerToInvite] then
					ActiveInvites[playerToInvite] = {};
				end
				if table.find(ActiveInvites[playerToInvite], lineOwner.Name) then
					return "Player already invited";
				end

				table.insert(ActiveInvites[playerToInvite], lineOwner.Name);
				EventToClient:FireClient(playerToInvite, "LineInvite", {lineOwner.Name});

				coroutine.wrap(function()
					for i = 0, 100 do
						local index = table.find(ActiveInvites[playerToInvite], lineOwner.Name);
						if not index then
							break;
						end

						if i == 100 then
							table.remove(ActiveInvites[playerToInvite], index);
						end

						task.wait(0.1);
					end
				end)()

				return true;
			end
			return "Player already in line";
		end
		return "Player not found";
	end
	return "Line not created";
end
function BattlePermissions:RemovePlayerFromLine(playerNameToRemove, playerRemoving)
	local playerToRemove = Players:FindFirstChild(playerNameToRemove);
	if playerToRemove then
		if playerToRemove:GetAttribute("LineID") ~= BattlePermissions:GetPublicLineID() then
			RemovePlayerFromLine(playerToRemove, playerRemoving, false);
			return true;
		end
		return "Player not in line";
	end
	return "Player not found";
end
function BattlePermissions:AcceptLineInvite(playerToAccept, lineOwnerName)
	if ActiveInvites[playerToAccept] then
		local index = table.find(ActiveInvites[playerToAccept], lineOwnerName);
		if index then
			local lineOwner = Players:FindFirstChild(lineOwnerName);
			if lineOwner then
				if playerToAccept:GetAttribute("Loadout") == "Flag Bearer" and BattlePermissions:LineHasFlag(lineOwner:GetAttribute("LineID")) then
					return "Line already has flag";
				end

				table.remove(ActiveInvites[playerToAccept], index);
				AddPlayerToLine(playerToAccept, lineOwner);
				return true;
			end
			return "Line not found";
		end
		return "Player not invited";
	end
	return "No invites found";
end
function BattlePermissions:RejectLineInvite(playerToReject, lineOwnerName)
	if ActiveInvites[playerToReject] then
		local index = table.find(ActiveInvites[playerToReject], lineOwnerName);
		if index then
			table.remove(ActiveInvites[playerToReject], index);
			return true;
		end
		return "Player not invited";
	end
	return "No invites found";
end
function BattlePermissions:GetLineIDFromPlayerID(playerID)
	local seed = Random.new(playerID);
	return seed:NextInteger(-1000000000, 999999899);
end
function BattlePermissions:GetPublicLineID()
	return 1000000000;
end
function BattlePermissions:GetLineInfoFromID(lineID)
	for each, player in pairs(Players:GetPlayers()) do
		if player:GetAttribute("LineID") == lineID then
			return player:GetAttribute("LineName"), player:GetAttribute("LineIcon"), player:GetAttribute("LineTeamName");
		end
	end
end

return BattlePermissions;

local LocalTechFunctions = {}

-- Services --
local ReplicatedStorage = game:GetService("ReplicatedStorage");
local Players = game:GetService("Players");
local Debris = game:GetService("Debris");

-- Main Variables --
local Player = Players.LocalPlayer;
local Camera = workspace.CurrentCamera;
local PlayerGui = Player.PlayerGui;
local Sidebar = PlayerGui:WaitForChild("Sidebar");

-- Character Variables --
local Character = Player.Character or Player.CharacterAdded:Wait();
local HumanoidRootPart = Character:WaitForChild("HumanoidRootPart");
local Head = Character:WaitForChild("Head");
local AimClock = os.clock();

-- Modules --
local Modules = ReplicatedStorage:WaitForChild("Modules");
local SharedTechFunctions = require(Modules.SharedTechFunctions);

-- Local Functions --
local function PassedAimCooldown()
	if os.clock() - AimClock > 0.1 then
		AimClock = os.clock();
		return true;
	end
end
local function CreateFakeFireParts(fireParts)
	local fakeFireParts = {};

	for each, firePart in pairs(fireParts) do
		local fakeFirePart = firePart:Clone();
		fakeFirePart.Parent = workspace.Visuals;
		table.insert(fakeFireParts, fakeFirePart);
	end

	return fakeFireParts;
end

-- Module Functions --
function LocalTechFunctions:GetAllCharacters()
	local characters = {};
	for each, foundCharacter in pairs(workspace:GetChildren()) do
		if foundCharacter:FindFirstChild("Humanoid") then
			table.insert(characters, foundCharacter);
		end
	end
	return characters;
end
function LocalTechFunctions:GetWorldMousePosition(mousePosition, mouseParams)
	local screenToWorldRay = Camera:ViewportPointToRay(mousePosition.X, mousePosition.Y);
	local directionVector = screenToWorldRay.Direction * 10000;
	local raycastResult = workspace:Raycast(screenToWorldRay.Origin, directionVector, mouseParams);
	if raycastResult and raycastResult.Instance.Name ~= "Hitbox" then
		return raycastResult.Position;
	else
		return screenToWorldRay.Origin + directionVector;
	end
end
function LocalTechFunctions:UpdateCamera(deltaTime, tool, timeToAimIn, cameraFOVDefault, cameraFOVWhenAiming)
	local character = workspace:WaitForChild(Player.Name, 1); --fixes FOV from not resetting on death
	if character and character.Humanoid.Health > 0 then
		local objectSpace = (HumanoidRootPart.CFrame + Vector3.new(0, 1.5, 0)):ToObjectSpace(Head.CFrame);
		character.Humanoid.CameraOffset = objectSpace.Position;

		if tool and tool:GetAttribute("Aiming") and tool:GetAttribute("Mouse1Held") and Sidebar.Backings.Options.Toggles.CameraFX:GetAttribute("CurrentState") == "On" then
			local totalSteps = math.floor(timeToAimIn / deltaTime);
			local adjustment = (cameraFOVDefault - cameraFOVWhenAiming) / totalSteps;
			Camera.FieldOfView -= adjustment;
			if Camera.FieldOfView < cameraFOVWhenAiming then
				Camera.FieldOfView = cameraFOVWhenAiming;
			end
		elseif cameraFOVDefault then
			Camera.FieldOfView = cameraFOVDefault;
		end
	elseif cameraFOVDefault then
		Camera.FieldOfView = cameraFOVDefault;
	end

	return {};
end
function LocalTechFunctions:UpdateMeleeStance(input, tool)
	local AbsX = math.abs(input.Delta.X);
	local AbsY = math.abs(input.Delta.Y); math.abs(-1)
	if AbsX > 0 or AbsY > 0 then
		if input.Delta.X > 0 then
			tool:SetAttribute("MeleeStance", "Right");
		elseif input.Delta.X < 0 then
			tool:SetAttribute("MeleeStance", "Left");
		end
		if input.Delta.Y < 0 then
			if AbsY * 3 > AbsX then
				tool:SetAttribute("MeleeStance", "Top");
			end
		elseif input.Delta.Y > 0 then
			if AbsY * 3 > AbsX then
				tool:SetAttribute("MeleeStance", "Bottom");
			end
		end
	end
end
function LocalTechFunctions:ReplicateAim(mousePosition, tool)
	SharedTechFunctions:AimPlayer(Player, mousePosition, tool);
	if PassedAimCooldown() then
		tool.ToolEvent:FireServer({mousePosition, "ReplicateAim"});
	end
end
function LocalTechFunctions:DisplayFireEffects(fireStatus, fireParts, emissionDuration)
	if Sidebar.Backings.Options.Toggles.Particles:GetAttribute("CurrentState") == "On" then
		if fireStatus == "failed" then
			for each, firePart in pairs(fireParts) do
				if firePart.Name == "SideBlast" then
					for each, effect in pairs(firePart:GetChildren()) do
						if effect:IsA("ParticleEmitter") then
							effect:Emit(40);
						end
					end
				end
			end
		elseif fireStatus == "succeeded" then
			local fakeFireParts = CreateFakeFireParts(fireParts);

			for each, fakeFirePart in pairs(fakeFireParts) do
				for each, effect in pairs(fakeFirePart:GetChildren()) do
					if effect:IsA("ParticleEmitter") then
						effect:Emit(40);
					end
				end
			end

			task.wait(emissionDuration);

			for each, fakeFirePart in pairs(fakeFireParts) do
				fakeFirePart.Anchored = true;
				fakeFirePart.WeldConstraint:Destroy();
				Debris:AddItem(fakeFirePart, 30);
			end
		end
	end
end

return LocalTechFunctions

local Permissions = {}

local ReplicatedStorage = game:GetService("ReplicatedStorage");
local ServerStorage = game:GetService("ServerStorage");
local GroupService = game:GetService("GroupService");
local RunService = game:GetService("RunService");
local groupID = 33078943; --Camden at home
local permissions = {
	[255] = 5, --Genre Owner
	[254] = 4, --Genre Manager
	[253] = 3, --Developer
	[252] = 3, --Coordinator
	[251] = 2, --Moderator
};
local Modules = ReplicatedStorage:WaitForChild("Modules");
local BattlePermissions = require(Modules:WaitForChild("BattlePermissions"));

function Permissions:GetPlayerPermissionRank(player)
	if RunService:IsStudio() then
		return permissions[255];
	end

	local playerRankInGroup = player:GetRankInGroup(groupID);

	--[[if typeof(player) ~= "number" then
		playerRankInGroup = player:GetRankInGroup(groupID);
	else
		local success, list = pcall(GroupService.GetGroupsAsync, GroupService, player)
		if success then
			for _, group in pairs(list) do
				if group.Id == groupID then
					playerRankInGroup = group.Rank;
					break;
				end
			end

			if not playerRankInGroup then
				playerRankInGroup = 0;
			end
		end
	end--]]

	if playerRankInGroup then
		if playerRankInGroup < 251 then
			if typeof(player) ~= "number" then
				if ReplicatedStorage:GetAttribute("PrivateServerOwnerId") == player.UserId then
					return 1; --Server Owner
				end
			end
		else
			return permissions[playerRankInGroup]
		end
	end
	return 0;
end

function Permissions:CanExecutorActOnPlayer(executor, player)
	local executorRank = Permissions:GetPlayerPermissionRank(executor);
	local playerRank = Permissions:GetPlayerPermissionRank(player);

	if not executorRank and not playerRank then
		return "failedBoth"
	elseif not executorRank then
		return "failedExecutor"
	elseif not playerRank then
		return "failedPlayer"
	end

	return executorRank >= playerRank
end

return Permissions

local SharedTechFunctions = {}

-- Services --
local ReplicatedStorage = game:GetService("ReplicatedStorage");
local RunService = game:GetService("RunService");
local Players = game:GetService("Players");

-- Aim Variables --
local base1 = CFrame.new(-1, 0.5, 0, 0, 0, -1, 0, 1, 0, 1, 0, 0);
local base2 = CFrame.new(1, 0.5, 0, 0, 0, 1, 0, 1, 0, -1, -0, -0);
local base3 = CFrame.new(0, 1, 0, -1, 0, 0, 0, 0, 1, 0, 1, -0);

-- Sapper Variables --
local sapperParams = OverlapParams.new();
sapperParams.FilterType = Enum.RaycastFilterType.Include;
sapperParams.FilterDescendantsInstances = {workspace.Structures, workspace.Map.Border, workspace.Map.Trees, workspace.Map.Nature, workspace.Map.Animals};

-- Modules --
local Modules = ReplicatedStorage:WaitForChild("Modules");
local PlayerSettings = require(Modules:WaitForChild("PlayerSettings"));

-- Local Functions --
local function ActiveTool6DExists(tool, torso)
	for each, thing in pairs(torso:GetChildren()) do
		if thing:GetAttribute("ActiveTool6D") then
			return true;
		end
	end
end
local function GetActiveTool6D(tool, torso)
	local motor6D = torso:FindFirstChild(tool.Name.."6D");
	if motor6D and tool.Parent == torso.Parent then
		return motor6D;
	end
end
local function ResetAim(lShoulder, rShoulder, neck, tool6D)
	lShoulder.C0 = base1;
	rShoulder.C0 = base2;
	neck.C0 = base3;
	if tool6D then
		tool6D.C0 = CFrame.new();
	end
end
local function SetAim(lShoulder, rShoulder, neck, tool6D, mainTor, headTor)
	lShoulder.C0 = mainTor * base1;
	rShoulder.C0 = mainTor * base2;
	neck.C0 = headTor * base3;
	tool6D.C0 = mainTor;
end

-- Module Functions --
function SharedTechFunctions:IsSapperPlacementGood(torso, mousePosition)
	if (torso.Position - mousePosition).Magnitude <= PlayerSettings.PlaceDistance then
		if mousePosition.Y <= PlayerSettings.MaximumHeightLimit and mousePosition.Y >= PlayerSettings.MinimumHeightLimit then
			local passedSpawnPadCheck = true;

			for each, spawnPad in pairs(workspace.Map.Spawns:GetChildren()) do
				if (spawnPad.Position - mousePosition).Magnitude <= PlayerSettings.SpawnPadPlaceDistance then
					passedSpawnPadCheck = false;
					break;
				end
			end

			if passedSpawnPadCheck then
				local passedOverlapCheck = true;

				local overlapParts = workspace:GetPartBoundsInRadius(mousePosition, 1, sapperParams);
				if overlapParts[1] then
					for each, part in pairs(overlapParts) do
						if not SharedTechFunctions:IsDescendantOfSpecificCharacter(part, torso.Parent) then
							if part.Name ~= "Hitbox" then
								passedOverlapCheck = false;
								break;
							end
						end
					end
				end

				if passedOverlapCheck then
					return true;
				end
				return "Overlapping something";
			end
			return "Too close to spawn";
		end
		return "Beyond height limit";
	end
	return "Too far away";
end
function SharedTechFunctions:AimPlayer(player, mousePosition, tool)
	local Character = player:IsA("Player") and (player.Character or player.CharacterAdded:Wait()) or player;
	local Head = Character:FindFirstChild("Head");
	local HumanoidRootPart = Character:FindFirstChild("HumanoidRootPart");
	local Torso = Character:FindFirstChild("Torso");
	if Head and HumanoidRootPart and Torso then
		local LShoulder = Torso:FindFirstChild("Left Shoulder");
		local RShoulder = Torso:FindFirstChild("Right Shoulder");
		local Neck = Torso:FindFirstChild("Neck");
		local RootJoint = HumanoidRootPart:FindFirstChild("RootJoint");
		if LShoulder and RShoulder and Neck and RootJoint then
			local Tool6D = GetActiveTool6D(tool, Torso);
			if Character.Humanoid.Health <= 0 then
				ResetAim(LShoulder, RShoulder, Neck);
			elseif Tool6D then
				if tool:GetAttribute("Aiming") or tool:GetAttribute("MeleeAiming") then
					local AimLocation = Vector3.new(mousePosition.X, HumanoidRootPart.Position.Y, mousePosition.Z);
					local headPos = Head.Position;
					local subVarAdjust = -0.5 * (mousePosition - headPos).Unit.Y;

					if tool:GetAttribute("MeleeAiming") then
						if subVarAdjust <= -0.15 then
							subVarAdjust = -0.15;
						elseif subVarAdjust >= 0.15 then
							subVarAdjust = 0.15;
						end
					elseif tool:GetAttribute("Aiming") then
						if subVarAdjust <= -0.45 then
							subVarAdjust = -0.45;
						elseif subVarAdjust >= 0.45 then
							subVarAdjust = 0.45;
						end
					end
					if RunService:IsClient() and (HumanoidRootPart.Position - AimLocation).Magnitude > 1 then
						HumanoidRootPart.CFrame = CFrame.new(HumanoidRootPart.Position, AimLocation);
					end

					if not player:IsA("Player") then
						HumanoidRootPart.CFrame = CFrame.new(HumanoidRootPart.Position, AimLocation);
					end

					local subVarAdjust2 = (0.5 + subVarAdjust) ^ 0.5 * 0.707;
					local subVarAdjust3 = (0.5 - subVarAdjust) ^ 0.5 * 0.707;
					local differenceCFrame = HumanoidRootPart.CFrame:ToObjectSpace(Torso.CFrame).Position;
					local headTor = Torso.CFrame:Inverse() * HumanoidRootPart.CFrame * (CFrame.new(0,1,0) + differenceCFrame) * CFrame.new(0, 0, 0, subVarAdjust3 - subVarAdjust2, 0, 0, subVarAdjust3 + subVarAdjust2) * (CFrame.new(0,1,0) + differenceCFrame):Inverse() * RootJoint.C0 * RootJoint.Transform * RootJoint.C1:Inverse();
					local mainTor = Torso.CFrame:Inverse() * HumanoidRootPart.CFrame * (CFrame.new(0,1.5,0) + differenceCFrame) * CFrame.new(0, 0, 0, subVarAdjust3 - subVarAdjust2, 0, 0, subVarAdjust3 + subVarAdjust2) * (CFrame.new(0,1.5,0) + differenceCFrame):Inverse() * RootJoint.C0 * RootJoint.Transform * RootJoint.C1:Inverse();

					SetAim(LShoulder, RShoulder, Neck, Tool6D, mainTor, headTor);
				else
					ResetAim(LShoulder, RShoulder, Neck, Tool6D);
				end
			elseif not ActiveTool6DExists(tool, Torso) then
				ResetAim(LShoulder, RShoulder, Neck);
			end
		end
	end
end
function SharedTechFunctions:IsDescendantOfAnyCharacter(instance)
	for each, character in pairs(workspace:GetChildren()) do
		if Players:GetPlayerFromCharacter(character) then
			if instance:IsDescendantOf(character) then
				return true;
			end
		end
	end
end
function SharedTechFunctions:IsDescendantOfSpecificCharacter(instance, character)
	for each, otherCharacter in pairs(workspace:GetChildren()) do
		if otherCharacter == character and Players:GetPlayerFromCharacter(otherCharacter) then
			if instance:IsDescendantOf(otherCharacter) then
				return true;
			end
		end
	end
end
function SharedTechFunctions:AddCommasToNumber(number)
	local formatted = number;

	while true do  
		formatted, k = string.gsub(formatted, "^(-?%d+)(%d%d%d)", '%1,%2');
		if k == 0 then
			break;
		end
	end

	return formatted;
end

return SharedTechFunctions

