function SpawnLocations:SpawnLocationIsValidForPlayer(spawnLocation, playerSpawning)
	if spawnLocation and spawnLocation.Parent and spawnLocation.Parent.Parent then
		if playerSpawning.TeamColor and spawnLocation:GetAttribute("TeamColor") and spawnLocation:GetAttribute("TeamColor") == playerSpawning.TeamColor then
			if spawnLocation.Parent == SpawnPads then -- spawn is a spawn pad
				return true;
			elseif spawnLocation.Parent:FindFirstChild("Flag") then --spawn is a flag bearer
				local flagTool = spawnLocation.Parent.Flag;
				if flagTool:GetAttribute("LastLineID") == playerSpawning:GetAttribute("LineID") then
					if not flagTool:GetAttribute("UnderCapture") then
						if spawnLocation.Parent.Humanoid.Health > 0 then
							if not flagTool:GetAttribute("SpawnsBlocked") then
								return true;
							end
							return "Spawning blocked";
						end
						return "Flag bearer is dead";
					end
					return "Flag is under capture";
				end
				return "Wrong regiment";
			elseif spawnLocation.Parent.Parent.Name == "Fort" then --spawn is a fort
				if not spawnLocation.Parent.Parent:GetAttribute("UnderCapture") then
					if spawnLocation.Parent.Parent:GetAttribute("Health") >= PlayerSettings.FortHealthNeededForSpawns then
						return true;
					end
					return "Fort health too low";
				end
				return "Spawning blocked";
			end
			return "Invalid spawn 1";
		end
		return "Wrong team";
	end
	return "Invalid spawn";
end
function SpawnLocations:SpawnLocationExistsForPlayer(spawnLocation, playerSpawning)
	if spawnLocation and spawnLocation.Parent and spawnLocation.Parent.Parent then
		if playerSpawning.TeamColor and spawnLocation:GetAttribute("TeamColor") and spawnLocation:GetAttribute("TeamColor") == playerSpawning.TeamColor then
			if spawnLocation.Parent == SpawnPads then -- spawn is a spawn pad
				return true;
			elseif spawnLocation.Parent:FindFirstChild("Flag") then --spawn is a flag bearer
				local flagTool = spawnLocation.Parent.Flag;
				if flagTool:GetAttribute("LastLineID") == playerSpawning:GetAttribute("LineID") then --or flagTool:GetAttribute("LineID") == BattlePermissions:GetPublicLineID()
					return true;
				end
				return "Wrong regiment";
			elseif spawnLocation.Name == "Fort" then --spawn is a fort
				return true;
			end
			return "Invalid spawn 2";
		end
		return "Wrong team";
	end
	return "Invalid spawn";
end
function SpawnLocations:GetSpawnLocationsForPlayer(playerSpawning)
	local currentSpawns = {};

	for each, spawnPad in pairs(SpawnPads:GetChildren()) do
		if typeof(SpawnLocations:SpawnLocationExistsForPlayer(spawnPad, playerSpawning)) == "boolean" then
			table.insert(currentSpawns, spawnPad);
		end
	end
	for each, character in pairs(workspace:GetChildren()) do
		local player = Players:GetPlayerFromCharacter(character);
		if player then
			local torso = character:FindFirstChild("Torso");
			if torso then
				if typeof(SpawnLocations:SpawnLocationExistsForPlayer(character.Torso, playerSpawning)) == "boolean" then
					table.insert(currentSpawns, character.Torso);
				end
			end
		end
	end
	for each, structure in pairs(workspace.Structures:GetChildren()) do
		if typeof(SpawnLocations:SpawnLocationExistsForPlayer(structure, playerSpawning)) == "boolean" then
			table.insert(currentSpawns, structure.Functional.Center);
		end
	end

	return currentSpawns;
end

return SpawnLocations

