	Aliases = {"activityreport"};
	Description = "Shows the current patrol times for all active moderators.";
	Group = "Moderator";
	Args = {};
}

local ServerStorage = game:GetService("ServerStorage");
local DataStoreService = game:GetService("DataStoreService");
local ServerModules = ServerStorage:WaitForChild("Modules");
local ProfileService = ServerModules:WaitForChild("ProfileService");
local PlayerData = ProfileService:WaitForChild("PlayerData");
local ProfileManager = require(PlayerData:WaitForChild("ProfileManager"));
local ModeratorLogs = require(ServerModules:WaitForChild("ModeratorLogs"));
local ProfileStore = ProfileManager:GetProfileStore();
local ActivityStore = DataStoreService:GetDataStore("ActivityReset");

local function GetTimeFormat(seconds)
	local hours = math.floor(seconds / 3600);
	local remainingSeconds = seconds % 3600;
	local minutes = math.floor(remainingSeconds / 60);
	return hours, minutes;
end

local function GetLastActivityResetTime()
	local data;
	local success, message = pcall(function()
		data = ActivityStore:GetAsync("Time");
	end)

	if data then
		return data;
	end
end

return function (context)
	local lastReset = GetLastActivityResetTime();
	if not lastReset then
		return "Unable to generate activity report, failed to read the last activity reset time.";
	end

	local moderators = ModeratorLogs:GetModerators();
	for each, moderator in pairs(moderators) do
		local profile = ProfileStore:ViewProfileAsync(tostring(moderator[1]));
		if profile then
			local patrolSeconds = profile.Data.PatrolTime;
			local lastOnline = profile.Data.LastOnline;
			if patrolSeconds and lastOnline and lastReset < lastOnline then
				moderator[3] = patrolSeconds;
			end
		end
	end

	context:Reply("----- Activity Report -----");
	for each, moderator in pairs(moderators) do
		if moderator[3] then
			local patrolHours, patrolMinutes = GetTimeFormat(moderator[3]);
			local hourString = patrolHours == 1 and patrolHours.." hour" or patrolHours.." hours";
			local minuteString = patrolMinutes == 1 and patrolMinutes.." minute" or patrolMinutes.." minutes";
			context:Reply(" ");
			context:Reply("- "..moderator[2].." -");
			context:Reply("Patrol Time: "..hourString.." and "..minuteString);
		else
			context:Reply(" ");
			context:Reply("- "..moderator[2].." -");
			context:Reply("This moderator hasn't joined the game since the last activity reset.");
		end
	end

	context:Reply(" ");
	return "----- Report End -----";
end

