	Aliases = {"view"};
	Description = "Keeps your camera over another player until they leave the game.";
	Group = "Server Owner";
	Args = {
		{
			Type = "player";
			Name = "player";
			Description = "The player to watch.";
		},
	};

	Run = function(context, viewPlayer)
		local viewCharacter = workspace:FindFirstChild(viewPlayer.Name);	
		if viewCharacter then
			local viewHumanoid = viewCharacter:FindFirstChild("Humanoid");
			if viewHumanoid then
				context.Executor:SetAttribute("Viewing", viewPlayer.Name);

				local camera = workspace.CurrentCamera;
				camera.CameraSubject = viewCharacter.Humanoid;

				if viewPlayer.Name ~= context.Executor.Name then
					local connection;
					connection = workspace.ChildAdded:Connect(function(newCharacter)
						local newHumanoid = newCharacter:WaitForChild("Humanoid", 3);
						if newHumanoid and newCharacter.Name == viewPlayer.Name then
							if context.Executor:GetAttribute("Viewing") == viewPlayer.Name then
								camera.CameraSubject = newHumanoid;
							else
								connection:Disconnect();
							end
						end
					end)
				else
					context.Executor:SetAttribute("Viewing", nil);
				end

				return "Viewing "..viewPlayer.Name..".";
			end
			return "Unable to view, could not find humanoid in the player model.";
		end
		return "Unable to view, could not find player model in Workspace.";
	end,
}

