end

return function (context, player, toolName)
	if not player.Backpack:FindFirstChild(toolName) and not player.Character:FindFirstChild(toolName) then
		if GetPlayerTools(player) < 4 then
			local realTool = Tools:FindFirstChild(toolName);
			if realTool then
				if (game.PrivateServerOwnerId == 0 and not RunService:IsStudio()) and realTool:GetAttribute("PrivateServerOnly") then
					return "Unable to give "..toolName..", that tool is for private servers only.";
