-- Local Functions --
local function AnimationMatchesCurrentStance(animationTrack, stanceType)
	if stanceType == "[" and string.sub(animationTrack.Name, 1, 2) ~= "[[" then
		return true;
	elseif stanceType == "[[" and string.sub(animationTrack.Name, 1, 2) == "[[" then
		return true;
	end
end
local function StopAllOtherAnimationsExceptFor(animationNames, animationTracks, stanceType)
	task.wait(0.2);
	for each, animationTrack in pairs(animationTracks) do
		if animationTrack.IsPlaying then
			local stanceMatches = AnimationMatchesCurrentStance(animationTrack, stanceType);
			if stanceMatches and not table.find(animationNames, animationTrack.Name) then
				animationTrack:Stop();
			end
		end
	end
end
local function PlayAnimationForDuration(animationTrack, animationObjects)
	if animationTrack then
		animationTrack:Play();
		ServerTechFunctions:AdjustTrackSpeed(animationTrack, animationObjects);
	end
end
local function GetMeleeDamageForTool(toolName, toolStance, isStructure, meleeStabDamage, meleeStabStructureDamage, meleeBashDamage, meleeBashStructureDamage)
	local meleeStance = ServerTechFunctions:GetMeleeStance(toolStance);
	if toolName == "Flag" then
		if meleeStance == "Bottom" then
			return (isStructure and meleeStabStructureDamage) or meleeStabDamage;
		end
		return (isStructure and meleeBashStructureDamage) or meleeBashDamage;
	elseif toolName == "Musket" then
		if meleeStance == "Top" or meleeStance == "Bottom" then
			return (isStructure and meleeStabStructureDamage) or meleeStabDamage;
		end
		return (isStructure and meleeBashStructureDamage) or meleeBashDamage;
	elseif toolName == "Rifle" then
		return (isStructure and meleeBashStructureDamage) or meleeBashDamage;
	elseif toolName == "Axe" then
		return (isStructure and meleeStabStructureDamage) or meleeStabDamage;
	elseif toolName == "Shovel" then
		if meleeStance == "Left" or meleeStance == "Right" then
			return (isStructure and meleeStabStructureDamage) or meleeStabDamage;
		end
		return (isStructure and meleeBashStructureDamage) or meleeBashDamage;
	end
end

-- Module Functions --
function ServerTechFunctions:PlaySound(soundNames, soundFolder, partToPlayIn)
	local soundsToGet = string.split(soundNames, ", ");
	local soundToPlay;

	for each, soundName in pairs(soundsToGet) do
		if soundName == "Grunt" or soundName == "Flesh" or soundName == "Blunt" or soundName == "Clang" then
			soundToPlay = soundFolder.Combat[soundName][soundName..RNG:NextInteger(1, #soundFolder.Combat[soundName]:GetChildren())];
		elseif soundName == "Fire" or soundName == "Construct" or soundName == "Dig" or soundName == "Dirt" or soundName == "Chop" then
			soundToPlay = soundFolder[soundName][soundName..RNG:NextInteger(1, #soundFolder[soundName]:GetChildren())];
		else
			soundToPlay = soundFolder:FindFirstChild(soundName, true);
		end

		local soundToPlay = soundToPlay:Clone();
		soundToPlay.Parent = partToPlayIn;
		soundToPlay:Play();
		if not soundToPlay.Looped then
			Debris:AddItem(soundToPlay, soundToPlay.TimeLength);
		end
	end
end
function ServerTechFunctions:DeleteSound(soundNames, partPlayingIn)
	local soundsToGet = string.split(soundNames, ", ");
	for each, sound in pairs(partPlayingIn:GetChildren()) do
		if table.find(soundsToGet, sound.Name) then
			sound:Destroy();
		end
	end
end
function ServerTechFunctions:ToggleToolVisibility(toggle, toolFolder, bayonetEquipped, bayonetAvailable)
	for each, part in pairs(toolFolder:GetDescendants()) do
		if part:GetAttribute("TTV") then
			if part.Name == "Bayonet" then
				part.Transparency = (toggle and bayonetEquipped and bayonetAvailable and 0) or 1;
			elseif part.Name == "Cartridge" or part.Name == "Horn" or part.Name == "Starter" or part.Name == "Lead" or part.Name == "Cloth" then
				part.Transparency = 1;
			else
				part.Transparency = (toggle and 0) or 1;
			end
		end
	end
end
function ServerTechFunctions:GetShootingParams(shooter)
	local shootingParams = RaycastParams.new();
	shootingParams.FilterType = Enum.RaycastFilterType.Include;
	shootingParams.IgnoreWater = true;

	local filter = {workspace.Map, workspace.Structures, workspace.Targets, workspace.Terrain};
	local teamName = shooter:IsA("Player") and shooter.Team.Name or shooter:GetAttribute("TeamName");
	for each, foundCharacter in pairs(workspace:GetChildren()) do
		local foundPlayer = Players:GetPlayerFromCharacter(foundCharacter);
		if foundPlayer and foundPlayer.Team.Name ~= teamName and foundCharacter:FindFirstChild("Hitbox") then
			table.insert(filter, foundCharacter.Hitbox);
		end
	end
	for each, regiment in pairs(workspace.Bots.Regiments:GetChildren()) do
		for each, foundBot in pairs(regiment.Members:GetChildren()) do
			if foundBot:GetAttribute("TeamName") ~= teamName and foundBot:FindFirstChild("Hitbox") then
				table.insert(filter, foundBot.Hitbox);
			end
		end
	end

	shootingParams.FilterDescendantsInstances = filter;

	return shootingParams;
end
function ServerTechFunctions:IsToolEquipped(tool)
	return tool:IsDescendantOf(workspace);
end
function ServerTechFunctions:CharacterHasForceField(character)
	return character:FindFirstChild("ForceFieldEffect");
end
function ServerTechFunctions:AssembleFireEffects(toolFolder)
	local fireEffects = {};

	for each, thing in pairs(toolFolder:GetDescendants()) do
		if thing:IsA("ParticleEmitter") or thing:IsA("SpotLight") then
			table.insert(fireEffects, thing);
		end
	end

	return fireEffects;
end
function ServerTechFunctions:GetCharacterWeapon(targetCharacter, targetPlayer)
	for each, potentialWeapon in pairs(targetCharacter:GetChildren()) do
		if potentialWeapon:IsA("Tool") and potentialWeapon:FindFirstChild("Settings") then
			return potentialWeapon;
		end
	end
	if targetPlayer then
		for each, potentialWeapon in pairs(targetPlayer.Backpack:GetChildren()) do
			if potentialWeapon:IsA("Tool") and potentialWeapon:FindFirstChild("Settings") then
				return potentialWeapon;
			end
		end
	end
end
function ServerTechFunctions:DamageCharacter(targetCharacter, targetPlayer, shooterPlayer, damage, distance, bleed, damageType, instaKillRange)
	if targetCharacter.Humanoid.Health > 0 then
		if not (targetPlayer and targetPlayer:GetAttribute("HealthGod")) then
			local damageToDeal = (distance <= instaKillRange and math.huge or damage);

			if shooterPlayer then
				damageToDeal = shooterPlayer:GetAttribute("Morale") > PlayerSettings.MoraleThresholdForTicketPenalty and damageToDeal or 0;
				if damageToDeal > 0 then
					targetCharacter:SetAttribute("DamagedBy", shooterPlayer.Name);
					targetCharacter:SetAttribute("DamageDistance", math.floor(distance));
					targetCharacter:SetAttribute("Damaged", true);
				end

				if damageType == "firearm" then
					EventToClient:FireClient(shooterPlayer, "RangePing");
				end
			else
				targetCharacter:SetAttribute("DamagedBy", "Bot");
				targetCharacter:SetAttribute("DamageDistance", math.floor(distance));
				targetCharacter:SetAttribute("Damaged", true);
			end

			if damageToDeal > 0 then
				if bleed then
					targetCharacter:SetAttribute("BleedingWounds", targetCharacter:GetAttribute("BleedingWounds") + 1);
					targetCharacter:SetAttribute("Bleeding", true);
				end
				targetCharacter.Humanoid:TakeDamage(damageToDeal);
			end
		end
	end
end
function ServerTechFunctions:DamageStructure(structureHit, structureDamage)
	local newHealth = math.clamp(structureHit:GetAttribute("Health") - structureDamage, 0, structureHit:GetAttribute("MaxHealth"));
	structureHit:SetAttribute("Health", newHealth);
end
function ServerTechFunctions:MeleeDamageStructure(structureHit, structureDamage, soundsFolder, shooterBodyAttach)
	ServerTechFunctions:PlaySound("Blunt", soundsFolder, shooterBodyAttach);
	local newHealth = math.clamp(structureHit:GetAttribute("Health") - structureDamage, 0, structureHit:GetAttribute("MaxHealth"));
	structureHit:SetAttribute("Health", newHealth);
end
function ServerTechFunctions:MeleeDamageCharacter(targetCharacter, targetPlayer, shooterPlayer, distance, damage, stabDamage, bashDamage, soundsFolder, shooterBodyAttach)
	if damage == stabDamage then
		ServerTechFunctions:PlaySound("Flesh", soundsFolder, shooterBodyAttach);
		ServerTechFunctions:DamageCharacter(targetCharacter, targetPlayer, shooterPlayer, damage, distance, true, "melee", 0);
	elseif damage == bashDamage then
		ServerTechFunctions:PlaySound("Blunt", soundsFolder, shooterBodyAttach);
