			local playerAttackDirection = ServerTechFunctions:GetMeleeStance(attackerStance);
			local targetPosition = targetCharacter.Hitbox.Position;
			local targetCFrame = targetCharacter.Head.CFrame;
			local thetaAngle = math.deg(math.acos(targetCFrame.LookVector:Dot((attackerPosition - targetPosition).Unit)));
			--if thetaAngle <= maximumAttackAngle then
				if targetBlockDirection == "Top" and playerAttackDirection == "Top" then
					return true;
				end
				if targetBlockDirection == "Bottom" and playerAttackDirection == "Bottom" then
					return true;
				end
				if targetBlockDirection == "Left" and playerAttackDirection == "Right" then
					return true;
				end
				if targetBlockDirection == "Right" and playerAttackDirection == "Left" then
					return true;
				end
			--end
		end
	end
end
function ServerTechFunctions:GetTargetCharacterFromHit(hit, hitter)
	local potentialCharacter = hit.Parent;
	if hit.Name == "Hitbox" and potentialCharacter:IsA("Model") and potentialCharacter ~= hitter then
		if SharedTechFunctions:IsDescendantOfAnyCharacter(hit) or hit:IsDescendantOf(workspace.Targets) or hit:IsDescendantOf(workspace.Bots) then
			return potentialCharacter;
		end
	end
end
function ServerTechFunctions:CreateAnimationTracks(animationsFolder, humanoid)
	local animationObjects = {};
	local animationTracks = {};

	for each, animation in pairs(animationsFolder:GetDescendants()) do
		if animation:IsA("Animation") then
			if not humanoid:FindFirstChildOfClass("Animator") then
				local animator = Instance.new("Animator", humanoid);
			end
			animationObjects[animation.Name] = animation;
			animationTracks[animation.Name] = humanoid.Animator:LoadAnimation(animation);
		end
	end

	return animationObjects, animationTracks;
end
function ServerTechFunctions:AdjustTrackSpeed(animationTrack, animationObjects, penalty)
	if animationTrack then
		local animationSpeed = animationObjects[animationTrack.Name]:GetAttribute("AnimationSpeed");
		if animationSpeed then
			local trackSpeed = animationTrack.Length / animationSpeed;
			if penalty then
				animationTrack:AdjustSpeed(trackSpeed * penalty);
			else
				animationTrack:AdjustSpeed(trackSpeed);
			end
		end
	end
end
function ServerTechFunctions:PlayAnimations(movement, idle, stanceType, animationTracks, animationObjects)
	if movement and idle then
