function ServerTechFunctions:FindTargetToMelee(toolName, toolHitbox, attackerPlayer, attackerCharacter, attackerHead, attackerHitbox, meleeStabDamage, meleeStabStructureDamage, meleeBashDamage, meleeBashStructureDamage, toolStance, maximumMeleeAngle, soundFolder, bodyAttach)
	local MeleeParams = OverlapParams.new();
	MeleeParams.FilterType = Enum.RaycastFilterType.Exclude;
	MeleeParams.FilterDescendantsInstances = {workspace.Map};

	local hitParts = workspace:GetPartsInPart(toolHitbox, MeleeParams);
	if hitParts then
		for each, hitPart in pairs(hitParts) do
			local targetCharacter = ServerTechFunctions:GetTargetCharacterFromHit(hitPart, attackerCharacter);
			if targetCharacter and not ServerTechFunctions:CharacterHasForceField(targetCharacter) then
				local distance = (attackerHitbox.Position - hitPart.Position).Magnitude;
				local targetIsParying = ServerTechFunctions:TargetIsParying(targetCharacter, attackerPlayer, toolStance, attackerHead.Position, maximumMeleeAngle);
				if targetIsParying then
					ServerTechFunctions:PlaySound("Clang", soundFolder, bodyAttach);
				else
					local targetPlayer = Players:GetPlayerFromCharacter(targetCharacter);
					local meleeDamage = GetMeleeDamageForTool(toolName, toolStance, false, meleeStabDamage, meleeStabStructureDamage, meleeBashDamage, meleeBashStructureDamage);
					if targetPlayer and targetPlayer.Team ~= attackerPlayer.Team and targetPlayer:GetAttribute("Spawned") then
						ServerTechFunctions:MeleeDamageCharacter(targetCharacter, targetPlayer, attackerPlayer, distance, meleeDamage, meleeStabDamage, meleeBashDamage, soundFolder, bodyAttach);
					elseif not targetPlayer then
						ServerTechFunctions:MeleeDamageCharacter(targetCharacter, targetPlayer, attackerPlayer, distance, meleeDamage, meleeStabDamage, meleeBashDamage, soundFolder, bodyAttach);
					end
				end
				return false;
			else
				if hitPart.Parent and hitPart.Parent.Parent and hitPart.Parent.Parent.Name == "Healths" then
					local structureHit = hitPart.Parent.Parent.Parent;
					local meleeDamage = GetMeleeDamageForTool(toolName, toolStance, false, meleeStabDamage, meleeStabStructureDamage, meleeBashDamage, meleeBashStructureDamage);
					if attackerPlayer.TeamColor ~= structureHit:GetAttribute("TeamColor") then
						ServerTechFunctions:MeleeDamageStructure(structureHit, meleeDamage, soundFolder, bodyAttach);
					end
					return false;
				end
			end
		end
	end

	return true;
end
function ServerTechFunctions:VerifyProjectileRaycastIsLegit(targetCharacter, shooterHead, shooterHitbox, toolFolder, raycastParams, maximumRange, maximumAimAngle)
	local shooterPosition = shooterHead.Position;
	local shooterCFrame = shooterHead.CFrame;
	local muzzlePosition = toolFolder.Muzzle.Position;
	local targetPosition = targetCharacter.Hitbox.Position;
	local distance = (shooterHitbox.Position - targetPosition).Magnitude;
	local thetaAngle = math.deg(math.acos(shooterCFrame.LookVector:Dot((targetPosition - shooterPosition).Unit)));
	--local clippingResult = workspace:Raycast(shooterPosition, muzzlePosition - shooterPosition, raycastParams);
	--if not clippingResult then --Shooter isn't sticking weapon through a wall
		if distance <= maximumRange then --Shooter is in range of the target
			if thetaAngle < maximumAimAngle then --Shooter is looking at the target
				return distance;
			end
		end
	--end
end
function ServerTechFunctions:ShootProjectile(shooterCharacter, shooterPlayer, raycastParams, toolFolder, endPosition, minSpread, maxSpread, maxRange, maxAimAngle, ammoDamage, ammoStructureDamage, debugEnabled, visualizeRaycasts, raycastsExpire, instaKillRange)
	if toolFolder and toolFolder:FindFirstChild("Muzzle") then
		local startPosition = toolFolder.Muzzle.Position;
		local spreadCoefficient = (minSpread - maxSpread) / PlayerSettings.AccuracyMaximum;
		local accuracy = (shooterPlayer and shooterPlayer:GetAttribute("Accuracy")) or shooterCharacter:GetAttribute("Accuracy");
		local spread = (spreadCoefficient * accuracy) + maxSpread;
		local direction = CFrame.new(startPosition, endPosition).LookVector + Vector3.new(RNG:NextNumber(-0.001, 0.001), RNG:NextNumber(-0.0001, 0.0001), RNG:NextNumber(-0.001, 0.001)) * spread;
		local vectorToShootOn = direction * maxRange;
		local projectileResult = workspace:Raycast(startPosition, vectorToShootOn, raycastParams);

		if projectileResult and projectileResult.Instance then
			local targetCharacter = ServerTechFunctions:GetTargetCharacterFromHit(projectileResult.Instance, shooterCharacter);
			if targetCharacter then
				if not ServerTechFunctions:CharacterHasForceField(targetCharacter) then
					local distanceFromLegitRaycast = ServerTechFunctions:VerifyProjectileRaycastIsLegit(targetCharacter, shooterCharacter.Head, shooterCharacter.Hitbox, toolFolder, raycastParams, maxRange, maxAimAngle);
					if distanceFromLegitRaycast then
						local targetPlayer = Players:GetPlayerFromCharacter(targetCharacter);
						if not shooterPlayer then --shooter is a bot
							ServerTechFunctions:DamageCharacter(targetCharacter, targetPlayer, shooterPlayer, ammoDamage, distanceFromLegitRaycast, true, "firearm", instaKillRange);
						elseif targetPlayer and targetPlayer.Team ~= shooterPlayer.Team and targetPlayer:GetAttribute("Spawned") then
							ServerTechFunctions:DamageCharacter(targetCharacter, targetPlayer, shooterPlayer, ammoDamage, distanceFromLegitRaycast, true, "firearm", instaKillRange);
						elseif not targetPlayer then
							ServerTechFunctions:DamageCharacter(targetCharacter, targetPlayer, shooterPlayer, ammoDamage, distanceFromLegitRaycast, true, "firearm", instaKillRange);
						end
					end
				end
			else
				local potentialStructurePiece = projectileResult.Instance;
				if potentialStructurePiece.Parent and potentialStructurePiece.Parent.Parent and potentialStructurePiece.Parent.Parent.Name == "Healths" then
					local structureHit = potentialStructurePiece.Parent.Parent.Parent;
					if shooterPlayer.TeamColor ~= structureHit:GetAttribute("TeamColor") then
						ServerTechFunctions:DamageStructure(structureHit, ammoStructureDamage);
					end
				else
					local potentialHawk = projectileResult.Instance;
					if shooterPlayer and potentialHawk.Name == "GEO_RedtailHawk_01" then
						EventToClient:FireClient(shooterPlayer, "KillNotification", {"Hawk", math.floor((potentialHawk.Position - shooterCharacter.Hitbox.Position).Magnitude)});
						CommonFunctions:AwardBadge(shooterPlayer, 3471003780872200, false);
					else
						--[[local bullet = script.Bullet:Clone();
					bullet.Position = projectileResult.Position;
					bullet.Parent = workspace.Visuals;
					Debris:AddItem(bullet, 10);--]]
					end
				end
			end

			for each, character in pairs(workspace:GetChildren()) do
				local player = Players:GetPlayerFromCharacter(character);
				local torso = character:FindFirstChild("Torso");
				if player and torso and (not shooterPlayer or player.Team ~= shooterPlayer.Team) then
					if (torso.Position - projectileResult.Position).Magnitude <= PlayerSettings.MoraleDistanceForShock then
						local newMorale = math.clamp(player:GetAttribute("Morale") + PlayerSettings.MoraleFromShock, 0, PlayerSettings.MoraleMaximum);
						player:SetAttribute("Morale", newMorale);
					end
				end
			end
		end

		if visualizeRaycasts and debugEnabled then
			local endPosition;
			if projectileResult then
				endPosition = projectileResult.Position;
			else
				endPosition = startPosition + vectorToShootOn;
			end
			local center = (startPosition + endPosition) / 2;

			local ray = Instance.new("Part");
			ray.Anchored = true;
			ray.CanCollide = false;
			ray.BrickColor = BrickColor.new("New Yeller");
			ray.Transparency = 0.5;
			ray.CFrame = CFrame.new(center, startPosition);
			ray.Size = Vector3.new(0.1, 0.1, (startPosition - endPosition).Magnitude);
			ray.Parent = workspace.Visuals;
			if raycastsExpire then
				Debris:AddItem(ray, 5);
			end
		end
	end
end
function ServerTechFunctions:GetClampedAccuracy(currentAccuracy, adjustment)
	return math.clamp(currentAccuracy + adjustment, 0, PlayerSettings.AccuracyMaximum);
end
function ServerTechFunctions:CharacterIsCrouching(character, tool)
	if tool.Name == "Rifle" then
		local playingAnimationTracks = ServerTechFunctions:GetPlayingAnimationTracks(character.Humanoid);
		for each, playingTrack in pairs(playingAnimationTracks) do
			if playingTrack.Name == "[[I]] Crouched" then
				return true;
			end
		end
	end
end
function ServerTechFunctions:UpdatePlayerAccuracy(deltaTime, player, character, tool, timeToAimIn, bayonetEquipped)
	local accuracy = (player and player:GetAttribute("Morale") or character:GetAttribute("Morale")) or PlayerSettings.MoraleMaximum;

	if tool:GetAttribute("Aiming") and tool:GetAttribute("Mouse1Held") then
		local totalSteps = math.floor(timeToAimIn / deltaTime);
		local adjustment = PlayerSettings.AccuracyBuffFromAiming / totalSteps;
		tool:SetAttribute("AimingBoost", tool:GetAttribute("AimingBoost") + adjustment);
		if tool:GetAttribute("AimingBoost") >= PlayerSettings.AccuracyBuffFromAiming then
			tool:SetAttribute("AimingBoost", PlayerSettings.AccuracyBuffFromAiming);
		end
	else
		tool:SetAttribute("AimingBoost", 0);
	end

	accuracy = ServerTechFunctions:GetClampedAccuracy(accuracy, (bayonetEquipped and PlayerSettings.AccuracyPenaltyFromBayonet) or 0);
	accuracy = ServerTechFunctions:GetClampedAccuracy(accuracy, (character.Humanoid.Health <= PlayerSettings.LowHealthThresholdForAccuracyPenalty and PlayerSettings.AccuracyPenaltyFromLowHealth) or 0);
	accuracy = ServerTechFunctions:GetClampedAccuracy(accuracy, (character.Humanoid.MoveDirection.Magnitude > 0 and PlayerSettings.AccuracyPenaltyFromMovement) or 0);
	accuracy = ServerTechFunctions:GetClampedAccuracy(accuracy, (ServerTechFunctions:CharacterIsCrouching(character, tool) and PlayerSettings.AccuracyBuffFromCrouching) or 0);
	accuracy = ServerTechFunctions:GetClampedAccuracy(accuracy, (character:GetAttribute("InRank") and PlayerSettings.AccuracyBuffFromInRank) or 0);
	accuracy = ServerTechFunctions:GetClampedAccuracy(accuracy, (tool:GetAttribute("Aiming") and tool:GetAttribute("Mouse1Held") and tool:GetAttribute("AimingBoost")) or 0);

	if player then
		player:SetAttribute("Accuracy", accuracy);
	else
		character:SetAttribute("Accuracy", accuracy);
	end
end
function ServerTechFunctions:UpdatePlayerWalkSpeed(player, animationObjects, bodyStance, toolStance)
	if animationObjects[toolStance] and animationObjects[bodyStance] then
		local weaponWalkSpeed = animationObjects[toolStance]:GetAttribute("WalkSpeed") or StarterPlayer.CharacterWalkSpeed;
		local bodyWalkSpeed = animationObjects[bodyStance]:GetAttribute("WalkSpeed") or StarterPlayer.CharacterWalkSpeed;
		if bodyWalkSpeed == StarterPlayer.CharacterWalkSpeed and weaponWalkSpeed > bodyWalkSpeed then
			player:SetAttribute("TargetWalkSpeed", math.max(weaponWalkSpeed, bodyWalkSpeed));
		else
			player:SetAttribute("TargetWalkSpeed", math.min(weaponWalkSpeed, bodyWalkSpeed));
		end
	end
end
function ServerTechFunctions:UpdateCharacterWalkSpeed(character, animationObjects, bodyStance, toolStance)
	if animationObjects[toolStance] and animationObjects[bodyStance] then
		local weaponWalkSpeed = animationObjects[toolStance]:GetAttribute("WalkSpeed") or StarterPlayer.CharacterWalkSpeed;
		local bodyWalkSpeed = animationObjects[bodyStance]:GetAttribute("WalkSpeed") or StarterPlayer.CharacterWalkSpeed;
		if bodyWalkSpeed == StarterPlayer.CharacterWalkSpeed and weaponWalkSpeed > bodyWalkSpeed then
			character.Humanoid.WalkSpeed = math.max(weaponWalkSpeed, bodyWalkSpeed);
		else
			character.Humanoid.WalkSpeed = math.min(weaponWalkSpeed, bodyWalkSpeed);
		end
	end
end
function ServerTechFunctions:UpdateCharacterReloadSpeed(character, animationObjects, animationTracks)
	local playingAnimationTracks = ServerTechFunctions:GetPlayingAnimationTracks(character.Humanoid);
	local reloadPenalty = 1;

	for each, playingTrack in pairs(playingAnimationTracks) do
		local animationObject = animationObjects[playingTrack.Name];
		if animationObject then
			local trackPenalty = animationObject:GetAttribute("ReloadPenalty") or 1;
			if trackPenalty < reloadPenalty then
				reloadPenalty = trackPenalty;
			end
		end
	end

	ServerTechFunctions:AdjustTrackSpeed(animationTracks["[M] Reload"], animationObjects, reloadPenalty);
	ServerTechFunctions:AdjustTrackSpeed(animationTracks["[M] ReloadFromShoulderArms"], animationObjects, reloadPenalty);
	ServerTechFunctions:AdjustTrackSpeed(animationTracks["[M] ReloadFromBayonetArms"], animationObjects, reloadPenalty);
end
function ServerTechFunctions:UpdateCharacterAttackSpeed(player, character, animationObjects, animationTracks)
	local playingAnimationTracks = ServerTechFunctions:GetPlayingAnimationTracks(character.Humanoid);
	local moralePenalty = math.clamp((player and player:GetAttribute("Morale") or character:GetAttribute("Morale") / PlayerSettings.MoraleMaximum) + 0.5, 0, 1);

	for each, playingTrack in pairs(playingAnimationTracks) do
		local animationObject = animationObjects[playingTrack.Name];
		if animationObject and animationObject:GetAttribute("AffectedByMorale") then
			ServerTechFunctions:AdjustTrackSpeed(animationTracks[playingTrack.Name], animationObjects, moralePenalty);
		end
	end
end
