local AntiExploitImmunity = {};

function AntiExploitImmunity:RevokePlayerImmunity(player)
	AntiExploitImmunity[player] = false;
end

function AntiExploitImmunity:GivePlayerImmunity(player, secondsOfImmunity)
	if not AntiExploitImmunity[player] then
		AntiExploitImmunity[player] = true;

		if secondsOfImmunity then
			coroutine.wrap(function()
				task.wait(secondsOfImmunity);
				AntiExploitImmunity:RevokePlayerImmunity(player);
			end)()
		end
	end
end

function AntiExploitImmunity:IsPlayerImmune(player)
	return AntiExploitImmunity[player];
end

return AntiExploitImmunity;

local RemoteSecurity = {};
local RemoteCooldowns = {};

function RemoteSecurity:PassedRemoteSecurity(remote, player, cooldown, arguments, types)
	-- Check if player exists --
	if not player or not player.Character then
		return false;
	end

	-- Check if player passed remote cooldown --
	if not RemoteCooldowns[player.Name] then
		RemoteCooldowns[player.Name] = {};
	end
	if not RemoteCooldowns[player.Name][remote.Name] then
		RemoteCooldowns[player.Name][remote.Name] = os.clock();
	elseif os.clock() - RemoteCooldowns[player.Name][remote.Name] < cooldown then
		return false;
	end
	RemoteCooldowns[player.Name][remote.Name] = os.clock();

	-- Check if player gave the right arguments --
	for index, argument in pairs(arguments) do
		if typeof(argument) ~= typeof(argument) then
			return false;
		end
		if typeof(argument) ~= types[index] then
			return false;
		end
		if typeof(argument) == "number" and (argument == math.huge or argument == -math.huge) then
			return false;
		end
	end

	-- Return true if all the checks didn't fail --
	return true;
end


return RemoteSecurity;

