local function FlagBearerCanReceiveFlag(player)
	if PlayerClasses:PlayerHasFlagInWorld(player) then
		return false;
	end
	if BattlePermissions:LineHasFlagActive(player:GetAttribute("LineID")) then
		return false;
	end
	return true;
end

function PlayerClasses:PlayerHasFlagInWorld(player)
	for each, flag in pairs(workspace.Flags:GetChildren()) do
		if flag:GetAttribute("LastOwnerName") == player.Name then
			return true;
		end
	end
	for each, character in pairs(workspace:GetChildren()) do
		local flagTool = character:FindFirstChild("Flag");
		if flagTool and flagTool:IsA("Tool") then
			if flagTool:GetAttribute("LastOwnerName") == player.Name then
				return true;
			end
		end
	end
end

function PlayerClasses:FlagBearerCanSpawnOnFlag(player)
	return not FlagBearerCanReceiveFlag(player);
end

function PlayerClasses:GivePlayerLoadout(player)
	local playerClass = player:GetAttribute("Loadout");
	local loadout = playerClass and ClassWeapons[playerClass];
	if loadout then
		for each, toolName in pairs(loadout) do
			if toolName == "Flag" and not FlagBearerCanReceiveFlag(player) then
				continue;
			end
			local tool = Tools[toolName]:Clone();
			tool.Parent = player.Backpack;
		end
	end
end

function PlayerClasses:ChangePlayerClass(player, className)
	if ClassWeapons[className] then
		if PlayerClasses:GetClassStatus(className) then
			player:SetAttribute("Loadout", className);
			if player.Character and player.Character:FindFirstChild("Humanoid") then
				player.Character.Humanoid:UnequipTools();
			end
			for each, tool in pairs(player.Backpack:GetChildren()) do
				tool:Destroy();
			end
			for each, toolName in pairs(ClassWeapons[className]) do
				local tool = Tools[toolName]:Clone();
				tool.Parent = player.Backpack;
			end

			--for each, structure in pairs(workspace.Structures:GetChildren()) do
			--	if structure:GetAttribute("OwnerName") == player.Name then
			--		structure:Destroy();
			--	end
			--end
			player:SetAttribute("Materials", PlayerSettings.StartingMaterials);

			return true;
		end
		return "Loadout is banned";
	end
	return "Invalid loadout";
end

function PlayerClasses:ClearPlayerClass(player)
	PlayerClasses[player] = nil;
end

