function PlayerClasses:SetClassStatus(class, toggle)
	ClassesAllowed[class] = toggle;
	if not toggle then
		for each, player in pairs(Players:GetPlayers()) do
			if player:GetAttribute("Loadout") == class then
				PlayerClasses:ChangePlayerClass(player, "Ranker");
			end
		end
	end
end

