function RankModule:SetRank(playerName, Rank)
	local url = "https://api.rankgun.works/roblox/set-rank?workspace_id="..WorkspaceId.."&rank="..Rank.."&username="..playerName
	local headers = {
		["Content-Type"] = "application/json",
		["api-token"] = ApiToken
	};
	local params = {
		workspace_id = WorkspaceId,
		username = playerName,
		rank = Rank
	};
	local requestBody = HttpService:JSONEncode(params);
	local request = {
		Url = url,
		Method = "POST",
		Headers = headers,
		Body = requestBody
	};

	local success, response = pcall(function()
		return HttpService:RequestAsync(request);
	end)

	if success then
		local responseBody = response.Body;
		local decodedResponse = HttpService:JSONDecode(responseBody);
	else
		warn("RankModule Failed to send request: ", response);
	end
end

return RankModule

