-- Module Functions --
function ModeratorLogs:RegisterModeratorOnline(player)
	ActiveMods[player] = os.time();
	SendWebhookToServer("Joining", {player.Name});
end
function ModeratorLogs:RegisterModeratorOffline(player)
	if ActiveMods[player] then
		local secondsOnline = os.time() - ActiveMods[player];
		local profile = ProfileManager.Profiles[player];
		if profile then
			profile.Data.PatrolTime += secondsOnline;
			local patrolHours, patrolMinutes = GetTimeFormat(profile.Data.PatrolTime);
			local hourString = patrolHours == 1 and patrolHours.." hour" or patrolHours.." hours";
			local minuteString = patrolMinutes == 1 and patrolMinutes.." minute" or patrolMinutes.." minutes";
			SendWebhookToServer("Leaving", {player.Name, hourString.." and "..minuteString});
		end
	end
end
function ModeratorLogs:LogCommand(commandType, data)
	if not RunService:IsStudio() then
		SendWebhookToServer(commandType, data);
	end
end
function ModeratorLogs:IsPlayerModerator(player)
	return player:GetRankInGroup(33078943) >= 251
end
function ModeratorLogs:GetModerators()
	return AllMods;
end

return ModeratorLogs;

