local Backing = GUI:WaitForChild("Backing")
local HealthBar = Backing:WaitForChild("HealthBar");
local HealthText = Backing:WaitForChild("HealthText");
local SapperText = GUI:WaitForChild("SapperText");

-- Modules --
local Modules = ReplicatedStorage:WaitForChild("Modules");
local PlayerSettings = require(Modules:WaitForChild("PlayerSettings"));
local SharedTechFunctions = require(Modules:WaitForChild("SharedTechFunctions"));

-- Health Functions --
local function UpdateStructureVisual(ratio)
	for each, structurePart in pairs(Healths:GetDescendants()) do
		if structurePart:IsA("BasePart") then
			structurePart.Transparency = (structurePart.Parent.Name == ratio and 0) or 1;
			structurePart.CanCollide = structurePart.Parent.Name == ratio;
			structurePart.CanQuery = structurePart.Parent.Name == ratio;
			structurePart.CanTouch = structurePart.Parent.Name == ratio;
		end
	end
end
local function UpdateAllFortsHealth(destroying)
	for each, potentialFort in pairs(workspace.Structures:GetChildren()) do
		if potentialFort.Name == "Fort" then
			local health = 0;
			local maxHealth = 0;

			for each, foundStructure in pairs(workspace.Structures:GetChildren()) do
				if not destroying or foundStructure ~= Structure then
					if potentialFort ~= foundStructure and foundStructure.Name ~= "Fort" then
						if (potentialFort.PrimaryPart.Position - foundStructure.PrimaryPart.Position).Magnitude <= PlayerSettings.FortStructureRange then
							health += foundStructure:GetAttribute("Health");
							maxHealth += foundStructure:GetAttribute("MaxHealth");
						end
					end
				end
			end

			potentialFort:SetAttribute("Health", health);
			potentialFort:SetAttribute("MaxHealth", maxHealth);
		end
	end
end
local function UpdateHealth()
	UpdateAllFortsHealth(false);

	local ratio = Structure:GetAttribute("Health") / Structure:GetAttribute("MaxHealth");
	HealthBar.Size = UDim2.new(ratio, 0, 1, 0);
	HealthText.Text = SharedTechFunctions:AddCommasToNumber(Structure:GetAttribute("Health")).." / "..SharedTechFunctions:AddCommasToNumber(Structure:GetAttribute("MaxHealth"));

	if ratio == 0 then
		UpdateStructureVisual("0");

		local SecondsAtZeroHealth = -1;
		while Structure:GetAttribute("Health") == 0 do
			SecondsAtZeroHealth += 1;
			if SecondsAtZeroHealth == PlayerSettings.StructureDecayTime then
				UpdateAllFortsHealth(true);
				Structure:Destroy();
			end
			task.wait(1);
		end
	elseif ratio <= 0.25 then
		UpdateStructureVisual("0.25");
	elseif ratio <= 0.5 then
		UpdateStructureVisual("0.5");
	elseif ratio <= 0.75 then
		UpdateStructureVisual("0.75");
	else
		UpdateStructureVisual("1");
	end
end

-- Structure Events --
Structure:GetAttributeChangedSignal("Health"):Connect(function()
	UpdateHealth();
end)
Structure:GetPropertyChangedSignal("Parent"):Connect(function()
	if Structure.Parent == workspace.Structures then
		SapperText.Text = "Sapper: "..Structure:GetAttribute("OwnerName");
		SapperText.TextColor = Structure:GetAttribute("TeamColor");
		GUI.Enabled = true;
		UpdateHealth();
	end
end)
