local SmallGUI = Center:WaitForChild("SmallGUI");
local LargeGUI = Center:WaitForChild("LargeGUI");
local Capturing = false;

-- Modules --
local Modules = ReplicatedStorage:WaitForChild("Modules");
local ServerModules = ServerStorage:WaitForChild("Modules");
local ServerTechFunctions = require(ServerModules:WaitForChild("ServerTechFunctions"));
