local Remotes = ReplicatedStorage:WaitForChild("Remotes");
local EventToClient = Remotes:WaitForChild("EventToClient");

-- Health Functions --
local function UpdateGUIs(valueType, value)
	if valueType == "HealthText" then
		SmallGUI.HealthBacking.HealthText.Text = value;
		LargeGUI.HealthBacking.HealthText.Text = value;
	elseif valueType == "HealthBar" then
		SmallGUI.HealthBacking.HealthBar.Size = value;
		LargeGUI.HealthBacking.HealthBar.Size = value;
	elseif valueType == "Capture" then
		SmallGUI.Capture.Visible = value;
		SmallGUI.CaptureBacking.Visible = value;
		LargeGUI.Capture.Visible = value;
		LargeGUI.CaptureBacking.Visible = value;
	elseif valueType == "CaptureText" then
		SmallGUI.CaptureBacking.CaptureText.Text = value;
		LargeGUI.CaptureBacking.CaptureText.Text = value;
	elseif valueType == "CaptureBar" then
		SmallGUI.CaptureBacking.CaptureBar.Size = value;
		LargeGUI.CaptureBacking.CaptureBar.Size = value;
	elseif valueType == "FortName" then
		SmallGUI.FortName.Text = value;
		LargeGUI.FortName.Text = value;
	elseif valueType == "SapperName" then
		SmallGUI.SapperName.Text = value;
	elseif valueType == "TextColor" then
		SmallGUI.SapperName.TextColor = value;
		SmallGUI.FortName.TextColor = value;
		LargeGUI.FortName.TextColor = value;
	end
end
local function UpdateHealthDisplays()
	local ratio = Structure:GetAttribute("Health") / Structure:GetAttribute("MaxHealth");
	local newText = SharedTechFunctions:AddCommasToNumber(Structure:GetAttribute("Health")).." / "..SharedTechFunctions:AddCommasToNumber(Structure:GetAttribute("MaxHealth"));
	local newSize = UDim2.new(ratio, 0, 1, 0);
	UpdateGUIs("HealthBar", newSize);
	UpdateGUIs("HealthText", newText); 
end
local function UpdateCaptureDisplays(secondsUnderCapture)
	local ratio = secondsUnderCapture / PlayerSettings.TimeToCaptureFort;
	local newText = math.floor(ratio * 100).."%";
	local newSize = UDim2.new(ratio, 0, 1, 0);
	UpdateGUIs("CaptureBar", newSize);
	UpdateGUIs("CaptureText", newText); 
end
local function UpdateHealth()
	UpdateHealthDisplays();

	if Structure:GetAttribute("MaxHealth") == 0 or Structure:GetAttribute("Health") / Structure:GetAttribute("MaxHealth") == 0 then
		coroutine.wrap(function()
			local SecondsAtZeroHealth = 0;
			while Structure:GetAttribute("Health") == 0 do
				task.wait(1);
				SecondsAtZeroHealth += 1;
				if SecondsAtZeroHealth == PlayerSettings.StructureDecayTime then
					Structure:Destroy();
				end
			end
		end)()
	end
end

local function CalculateHealth()
	local health = 0;
	local maxHealth = 0;

	for each, foundStructure in pairs(workspace.Structures:GetChildren()) do
		if Structure ~= foundStructure and foundStructure.Name ~= "Fort" then
			if (Structure.PrimaryPart.Position - foundStructure.PrimaryPart.Position).Magnitude <= PlayerSettings.FortStructureRange then
				health += foundStructure:GetAttribute("Health");
				maxHealth += foundStructure:GetAttribute("MaxHealth");
			end
		end
	end

	Structure:SetAttribute("Health", health);
	Structure:SetAttribute("MaxHealth", maxHealth);

	UpdateHealth();
end

-- Fort Loops --
local function StartFlagLoop()
	coroutine.wrap(function()
		while true do
			for i = 1, #FlagPieces:GetChildren() do
				local prevPiece = i - 1;
				if prevPiece == 0 then
					prevPiece = #FlagPieces:GetChildren();
				end

				FlagPieces[prevPiece].Transparency = 1;
				FlagPieces[i].Transparency = 0;

				task.wait(1/60);
			end
			task.wait();
		end
	end)()
end
local function StartCaptureLoop()
	coroutine.wrap(function()
		while true do
			local nearbyEnemies = {};

			for each, character in pairs(workspace:GetChildren()) do
				local player = Players:GetPlayerFromCharacter(character);
				if player and player.TeamColor ~= Structure:GetAttribute("TeamColor") then
					local torso = character:FindFirstChild("Torso")
					if torso and (torso.Position - Structure.PrimaryPart.Position).Magnitude <= PlayerSettings.DistanceToCaptureFort then
						if character.Humanoid.Health > 0 then
							table.insert(nearbyEnemies, character);
						end
					end
				end
			end

			Structure:SetAttribute("UnderCapture", #nearbyEnemies >= PlayerSettings.EnemiesNeededNearFortToCapture);

			task.wait(0.2);
		end
	end)()
end
local function GetOppositeTeamColor()
	return (Structure:GetAttribute("TeamColor") == BrickColor.new("Persimmon") and BrickColor.new("Electric blue")) or BrickColor.new("Persimmon");
end
local function GetTeamNameFromColor()
	return (Structure:GetAttribute("TeamColor") == BrickColor.new("Persimmon") and "Team1") or "Team2";
end
local function GetOppositeTeamName(teamName)
	return teamName == "Team1" and "Team2" or "Team1";
end
local function ConvertFort()
	Structure:SetAttribute("TeamColor", GetOppositeTeamColor());
	Center:SetAttribute("TeamColor", Structure:GetAttribute("TeamColor"));
	UpdateGUIs("TextColor", Structure:GetAttribute("TeamColor"));
	Structure:SetAttribute("UnderCapture", false);

	for each, foundStructure in pairs(workspace.Structures:GetChildren()) do
		if Structure ~= foundStructure and foundStructure.Name ~= "Fort" then
			if (Structure.PrimaryPart.Position - foundStructure.PrimaryPart.Position).Magnitude <= PlayerSettings.FortStructureRange then
				foundStructure:SetAttribute("TeamColor", Structure:GetAttribute("TeamColor"));
			end
		end
	end

	if ReplicatedStorage:GetAttribute("BattleStarted") then
		local teamName = GetTeamNameFromColor();
		local newTickets = math.clamp(ReplicatedStorage:GetAttribute(teamName.."Tickets") + PlayerSettings.TicketBonusForFortCapture, 0, math.huge);
		ReplicatedStorage:SetAttribute(teamName.."Tickets", newTickets);
		EventToClient:FireAllClients("NotifyFort", {ReplicatedStorage:GetAttribute(teamName.."Name"), Structure:GetAttribute("FortName")});
	end

	CalculateHealth();
end

