Structure:GetAttributeChangedSignal("Health"):Connect(function()
	UpdateHealth();
end)
Structure:GetAttributeChangedSignal("MaxHealth"):Connect(function()
	UpdateHealthDisplays();
end)
Structure:GetAttributeChangedSignal("FortName"):Connect(function()
	UpdateGUIs("FortName", Structure:GetAttribute("FortName"));
end)
Structure:GetAttributeChangedSignal("UnderCapture"):Connect(function()
	UpdateGUIs("Capture", Structure:GetAttribute("UnderCapture"));

	if Structure:GetAttribute("UnderCapture") and not Capturing then
		Capturing = true;

		local secondsUnderCapture = 0;
		while Structure:GetAttribute("UnderCapture") do
			UpdateCaptureDisplays(secondsUnderCapture);

			task.wait(1);

			if Structure:GetAttribute("UnderCapture") then
				local nearbyStallers = {};

				for each, character in pairs(workspace:GetChildren()) do
					local player = Players:GetPlayerFromCharacter(character);
					if player and player.TeamColor == Structure:GetAttribute("TeamColor") and character:FindFirstChild("Torso") then
						if (character.Torso.Position - Structure.PrimaryPart.Position).Magnitude <= PlayerSettings.DistanceToReinforceFort then
							if character.Humanoid.Health > 0 then
								table.insert(nearbyStallers, character);
							end
						end
					end
				end

				if #nearbyStallers < PlayerSettings.TeammatesNeededNearFortToBlockCapture then
					secondsUnderCapture += 1;
					if secondsUnderCapture == PlayerSettings.TimeToCaptureFort then
						ConvertFort();
					end
				end
			end
		end

		Capturing = false;
	end
end)
Structure:GetPropertyChangedSignal("Parent"):Connect(function()
	if Structure.Parent == workspace.Structures then
		Structure:SetAttribute("FortName", ServerTechFunctions:GetRandomStructureName("Fort"));
		Center:SetAttribute("TeamColor", Structure:GetAttribute("TeamColor"));
		UpdateGUIs("SapperName", "Sapper: "..Structure:GetAttribute("OwnerName"));
		UpdateGUIs("TextColor", Structure:GetAttribute("TeamColor"));

		local player = Players:FindFirstChild(Structure:GetAttribute("OwnerName"));
		for each, flagPiece in pairs(FlagPieces:GetChildren()) do
			flagPiece.BrickColor = Structure:GetAttribute("TeamColor");
			flagPiece.TextureID = player:GetAttribute("CustomFlag") == "" and "" or "rbxassetid://"..player:GetAttribute("CustomFlag");
		end

		SmallGUI.Enabled = true;
		LargeGUI.Enabled = true;
		for each, part in pairs(StructureFolder:GetChildren()) do
			if part:IsA("BasePart") and part.Name ~= "Pole" then
				part.CanCollide = true;
			end
		end

		CalculateHealth();
		--StartFlagLoop();
		StartCaptureLoop();
	end
end)

