-- Remote Functions --
TransferMaterials.OnServerInvoke = function(player, action, amount)
	local passed = RemoteSecurity:PassedRemoteSecurity(TransferMaterials, player, 2, {action, amount}, {"string", "number"});
	if passed then
		local ratio = Structure:GetAttribute("Health") / Structure:GetAttribute("MaxHealth");
		if ratio >= 0.25 then
			if PlayerInRange(player) then
				if player:GetAttribute("Loadout") == "Sapper" then
					if action ~= "Withdraw" or (action == "Withdraw" and player.TeamColor == Structure:GetAttribute("TeamColor")) then
						local actualAmount = math.floor(amount);
						if actualAmount > 0 then
							if action == "Deposit" then
								if player:GetAttribute("Materials") >= actualAmount then
									player:SetAttribute("Materials", player:GetAttribute("Materials") - actualAmount);
									Structure:SetAttribute("StoredMaterials", Structure:GetAttribute("StoredMaterials") + actualAmount);
									return true;
								end
								return "Not enough materials";
							elseif action == "Withdraw" then
								if Structure:GetAttribute("StoredMaterials") - actualAmount >= 0 then
									player:SetAttribute("Materials", player:GetAttribute("Materials") + actualAmount);
									Structure:SetAttribute("StoredMaterials", Structure:GetAttribute("StoredMaterials") - actualAmount);
									return true;
								end
								return "Not enough stored materials";
							end
							return "Invalid action";
						end
						return "Amount must be above 0";
					end
					return "Wrong team";
				end
				return "Not a sapper";
			end
			return "Out of range";
		end
		return "Cache health too low";
	end
	return "Transfering too fast";
end

