	if not Success then
		print("MessagingService:SubscribeAsync. Retrying")
		warn(Errormessage)
		wait(1)
	end	
until Success

local function teamNearStructure(structure)
	for each, player in pairs(Players:GetPlayers()) do
		if player.TeamColor == structure:GetAttribute("TeamColor") then
			local character = player.Character;
			if character then
				local torso = character:FindFirstChild("Torso");
				if torso then
					if (torso.Position - structure.PrimaryPart.Position).Magnitude <= 100 then
						return true;
					end
				end
			end
		end
	end
end

local function initialize()
	debug.setmemorycategory("Script_GameManager");

	coroutine.wrap(function()
		while true do
			ReplicatedStorage:SetAttribute("UptimeSecond", ReplicatedStorage:GetAttribute("UptimeSecond") + 1);
			if ReplicatedStorage:GetAttribute("UptimeSecond") == 60 then
				ReplicatedStorage:SetAttribute("UptimeMinute", ReplicatedStorage:GetAttribute("UptimeMinute") + 1);
				ReplicatedStorage:SetAttribute("UptimeSecond", 0);
				if ReplicatedStorage:GetAttribute("UptimeMinute") == 60 then
					ReplicatedStorage:SetAttribute("UptimeHour", ReplicatedStorage:GetAttribute("UptimeHour") + 1);
					ReplicatedStorage:SetAttribute("UptimeMinute", 0);
				end
			end

			task.wait(1);
		end
	end)()

	coroutine.wrap(function()
		while true do
			local storeVersion;
			local success, error = pcall(function()
				storeVersion = VersionStore:GetAsync("Version");
			end)

			if storeVersion then
				if not CurrentVersion then
					CurrentVersion = storeVersion;
					ReplicatedStorage:SetAttribute("ServerVersion", CurrentVersion);
				elseif CurrentVersion ~= storeVersion then
					ReplicatedStorage:SetAttribute("ServerStatus", 1);
				end
			end

			task.wait(15);
		end
	end)()

	coroutine.wrap(function()
		while true do
			for each, structure in pairs(workspace.Structures:GetChildren()) do
				if structure:GetAttribute("Decays") and not teamNearStructure(structure) then
					local newHealth = math.clamp(structure:GetAttribute("Health") - PlayerSettings.StructureWitherAmount, 0, math.huge);
					structure:SetAttribute("Health", newHealth);
				end
			end

			task.wait(60);
		end
	end)()
end
initialize();

