local function HandleLockedUpdate(profile, update)
	if update[2].UpdateType == "unban" then
		profile.Data.Moderations.IsBanned = false;
		profile.Data.Moderations.IsPermBanned = false;
		profile.Data.Moderations.CurrentBanReason = "";
		profile.Data.Moderations.CurrentModeratorWhoBanned = 0;
		profile.Data.Moderations.TimeWhenUnbanned = 0;
		table.insert(profile.Data.Moderations.PriorUnbans, {Moderator = update[2].ModeratorID, Reason = update[2].UnbanReason, ActionTime = update[2].UnbanTime});
	elseif update[2].UpdateType == "pban" then
		profile.Data.Moderations.IsBanned = true;
		profile.Data.Moderations.IsPermBanned = true;
		profile.Data.Moderations.CurrentBanReason = update[2].BanReason;
		profile.Data.Moderations.CurrentModeratorWhoBanned = update[2].ModeratorID;
		table.insert(profile.Data.Moderations.PriorBans, {Moderator = update[2].ModeratorID, Reason = update[2].BanReason, ActionTime = update[2].BanTime, BanType = "PERM"});
		for _, player in pairs(Players:GetPlayers()) do
			if player.UserId == update[2].PlayerID then
				player:Kick("You have been permanently banned for: "..update[2].BanReason..".");
				break;
			end
		end
	elseif update[2].UpdateType == "tban" then
		profile.Data.Moderations.IsBanned = true;
		profile.Data.Moderations.CurrentBanReason = update[2].BanReason;
		profile.Data.Moderations.CurrentModeratorWhoBanned = update[2].ModeratorID;
		profile.Data.Moderations.TimeWhenUnbanned = os.time() + (update[2].BanLength * 86400);
		table.insert(profile.Data.Moderations.PriorBans, {Moderator = update[2].ModeratorID, Reason = update[2].BanReason, ActionTime = update[2].BanTime, BanType = "TEMP"});
		for _, player in pairs(Players:GetPlayers()) do
			if player.UserId == update[2].PlayerID then
				if update[2].BanLength == 1 then
					player:Kick("You have been temporarily banned for "..update[2].BanLength.." day for: "..update[2].BanReason..".");
				else
					player:Kick("You have been temporarily banned for "..update[2].BanLength.." days for: "..update[2].BanReason..".");
				end
				break;
			end
		end
	elseif update[2].UpdateType == "wipeHistory" then
		profile.Data.Moderations = Template.Moderations;
	elseif update[2].UpdateType == "wipeActivity" then
		profile.Data.PatrolTime = Template.PatrolTime;
	end
	profile.GlobalUpdates:ClearLockedUpdate(update[1]);
end
local function GetPlayerData(player)
	if player:IsDescendantOf(Players) then
		local profile = ProfileStore:LoadProfileAsync(tostring(player.UserId));
		if profile == nil then
			player:Kick("LoadProfileAsync failed to get data.");
		else
			profile:AddUserId(player.UserId);
			profile:Reconcile();
			profile:ListenToRelease(function()
				ProfileManager.Profiles[player] = nil;
				player:Kick("ListenToRelease activated.");
			end)

			for _, playerId in pairs(Votekicked) do
				if player.UserId == playerId then
					player:Kick("You have been votekicked from this server!");
				end
			end
			for _, playerId in pairs(ServerBanned) do
				if player.UserId == playerId then
					player:Kick("You have been banned from this server!");
				end
			end
			if ServerLocked then
				player:Kick("This server is locked!");
			end

			local inOneGroup = #WhitelistedGroups == 0;
			for _, groupID in pairs(WhitelistedGroups) do
				if player:GetRankInGroup(groupID) > 0 then
					inOneGroup = true;
					break;
				end
			end
			if not inOneGroup then
				player:Kick("You are not in one of the whitelisted groups!");
			end

			if script:GetAttribute("PrivateWhitelist") and game.PrivateServerOwnerId == 0 then
				local passed = false;
				for each, authorizedID in pairs(WhitelistedPlayers) do
					if player.UserId == authorizedID then
						passed = true;
						break;
					end
				end
				if not passed then
					player:Kick("This game is under private play-testing with a whitelist. Join the communications if you're interested in becoming a play-tester.");
				end
			end

			if player:IsDescendantOf(Players) then
				ProfileManager.Profiles[player] = profile;

				for _, update in pairs(profile.GlobalUpdates:GetActiveUpdates()) do
					profile.GlobalUpdates:LockActiveUpdate(update[1]);
				end
				for _, update in pairs(profile.GlobalUpdates:GetLockedUpdates()) do
					HandleLockedUpdate(profile, update);
				end

				profile.GlobalUpdates:ListenToNewActiveUpdate(function(id, data)
					profile.GlobalUpdates:LockActiveUpdate(id);
				end)
				profile.GlobalUpdates:ListenToNewLockedUpdate(function(id, data)
					HandleLockedUpdate(profile, {id, data});
				end)

				if profile.Data.Moderations.IsBanned then
					if profile.Data.Moderations.IsPermBanned then
						player:Kick("You have been permanently banned for: "..profile.Data.Moderations.CurrentBanReason..".");
					elseif os.time() < profile.Data.Moderations.TimeWhenUnbanned then
						local daysLeft = math.ceil(math.abs(os.time() - profile.Data.Moderations.TimeWhenUnbanned)/86400);
						if daysLeft == 1 then
							player:Kick("You have been temporarily banned for "..daysLeft.." day for: "..profile.Data.Moderations.CurrentBanReason..".");
						elseif daysLeft > 1 then
							player:Kick("You have been temporarily banned for "..daysLeft.." days for: "..profile.Data.Moderations.CurrentBanReason..".");
						end
					else
						profile.Data.Moderations.IsBanned = false;
						profile.Data.Moderations.CurrentBanReason = "";
						profile.Data.Moderations.CurrentModeratorWhoBanned = 0;
						profile.Data.Moderations.TimeWhenUnbanned = 0;
					end
				end

				if player:IsDescendantOf(Players) then
					profile.Data.LastOnline = os.time();
					player:SetAttribute("HasFreecam", RunService:IsStudio() or game.PrivateServerOwnerId ~= 0 or CommonFunctions:CheckGamepassOwnership(player, 692856622, true));
				end
			else
				profile:Release();
			end
		end
	end
end
local function CharacterLoaded(player)
	local character = player.Character or player.CharacterAdded:Wait();

	player:SetAttribute("Spawned", false);
	player:SetAttribute("Morale", PlayerSettings.SpawningMorale);
	character:SetAttribute("Bleeding", false);
	character:SetAttribute("BleedingWounds", 0);
	character:SetAttribute("DamagedDistance", 0);
	character:SetAttribute("DamagedBy", "");
	character:SetAttribute("Damaged", false);
	character.Torso:SetAttribute("TeamColor", player.TeamColor);

	CreateCharacterIcon(player, character);
	CreateCharacterPart(player, character, Hitbox, Vector3.new(0, -0.4, 0));
	CreateCharacterPart(player, character, BleedPart, Vector3.new(0, 0, 0));

	for each, part in pairs(character:GetChildren()) do
		if part:IsA("BasePart") then
			part.CollisionGroup = player.Team.Name;
		end
	end

	local humanoid = character:FindFirstChild("Humanoid");
	if humanoid then
		local diedConnection;
		diedConnection = humanoid.Died:Connect(function()
			if character:GetAttribute("Damaged") then
				ReplicatedStorage:SetAttribute("Casualties", ReplicatedStorage:GetAttribute("Casualties") + 1);

				player:SetAttribute("Deaths", player:GetAttribute("Deaths") + 1);
				if not character:GetAttribute("DamagedBy") then
					character:SetAttribute("DamagedBy", "Bot");
				end
				EventToClient:FireClient(player, "DeathNotification", {character:GetAttribute("DamagedBy"), character:GetAttribute("DamageDistance")});

				local killerPlayer = Players:FindFirstChild(character:GetAttribute("DamagedBy"));
				if killerPlayer then
					killerPlayer:SetAttribute("Kills", killerPlayer:GetAttribute("Kills") + 1);
					killerPlayer:SetAttribute("Morale", math.clamp(killerPlayer:GetAttribute("Morale") + PlayerSettings.MoraleFromKill, 0, PlayerSettings.MoraleMaximum));
					EventToClient:FireClient(killerPlayer, "KillNotification", {player.Name, character:GetAttribute("DamageDistance")});
					EventToClient:FireAllClients("Feed", {killerPlayer, player, character:GetAttribute("DamageDistance")});

					if character:GetAttribute("DamageDistance") >= 300 then
						CommonFunctions:AwardBadge(killerPlayer, 3729493515352165, false);
					end
					if player.UserId == 42921866 then
						CommonFunctions:AwardBadge(killerPlayer, 86577869390323, false);
					end
					if killerPlayer:GetAttribute("Kills") >= 50 then
						CommonFunctions:AwardBadge(killerPlayer, 1987629096633147, false);
					end
				end

				for each, otherCharacter in pairs(workspace:GetChildren()) do
					if otherCharacter ~= character and otherCharacter:FindFirstChild("Hitbox") and character:FindFirstChild("Hitbox") then
						if (otherCharacter.Hitbox.Position - character.Hitbox.Position).Magnitude <= PlayerSettings.MoraleDistanceForTeammateDeath then
							local otherPlayer = Players:GetPlayerFromCharacter(otherCharacter);
							if otherPlayer and otherPlayer.Team == player.Team then
								otherPlayer:SetAttribute("Morale", math.clamp(otherPlayer:GetAttribute("Morale") + PlayerSettings.MoraleFromTeammateDeath, 0, PlayerSettings.MoraleMaximum));
							end
						end
					end
				end
			end
			if character:FindFirstChild("Head") then
				character.Head.Icon:Destroy();
			end

			task.wait(Players.RespawnTime);
			RespawnPlayer:Fire(player);
			diedConnection:Disconnect();
		end)

		while humanoid and humanoid.Health > 0 do
			task.wait(1);
			if not character:FindFirstChild("Hitbox") then
				CreateCharacterPart(player, player.Character, Hitbox, Vector3.new(0, -0.4, 0));
			end
			if not character:FindFirstChild("BleedPart") then
				CreateCharacterPart(player, player.Character, BleedPart, Vector3.new(0, 0, 0));
			end
		end
	end
end
