local function PlayerAlreadyHasFort(player)
	for each, structure in pairs(workspace.Structures:GetChildren()) do
		if structure.Name == "Fort" and structure:GetAttribute("OwnerName") == player.Name then
			return structure;
		end
	end
end
local function FortIsNearAnotherFort(fortPosition)
	for each, structure in pairs(workspace.Structures:GetChildren()) do
		if structure.Name == "Fort" then
			if (structure.PrimaryPart.Position - fortPosition).Magnitude <= PlayerSettings.DistanceBetweenForts then
				return true;
			end
		end
	end
end
local function StructureIsNearFort(structurePosition, teamColor)
	for each, structure in pairs(workspace.Structures:GetChildren()) do
		if structure.Name == "Fort" and structure:GetAttribute("TeamColor") == teamColor then
			if (structure.PrimaryPart.Position - structurePosition).Magnitude <= PlayerSettings.FortStructureRange then
				return true;
			end
		end
	end
end
local function GetPlayerFlagPieces(player, character)
	local flagTool = character:FindFirstChild("Flag");
	local fort = PlayerAlreadyHasFort(player);
	if flagTool then
		return flagTool.Flag.FlagPieces;
	elseif fort then
		return fort.Structure.FlagPieces;
	end
end
local function GetFilteredMessage(text, playerID)
	local textObject;
	local filteredMessage;

	local success, errorMessage = pcall(function()
		textObject = TextService:FilterStringAsync(text, playerID);
		filteredMessage = textObject:GetNonChatStringForBroadcastAsync();
	end)

	if not success then
		print("Error generating TextFilterResult:"..errorMessage);
	end
	return filteredMessage;
end
