	GetPlayerData(player);

	if player:IsDescendantOf(Players) then
		player:SetAttribute("Accuracy", PlayerSettings.AccuracyMaximum);
		player:SetAttribute("Spawned", false);
		player:SetAttribute("Kills", 0);
		player:SetAttribute("Deaths", 0);
		player:SetAttribute("Flags", 0);
		player:SetAttribute("CustomFlag", GetTeamFlag(player));
		player:SetAttribute("OwnsCustomFlag", (game.PrivateServerOwnerId ~= 0 or RunService:IsStudio()) or CommonFunctions:CheckGamepassOwnership(player, 684658312, true));
		player:SetAttribute("OwnsLineCreation", (game.PrivateServerOwnerId ~= 0 or RunService:IsStudio()) or CommonFunctions:CheckGamepassOwnership(player, 694761316, true));
		player:SetAttribute("HealthGod", script:GetAttribute("HealthGod"));
		player:SetAttribute("MoraleGod", script:GetAttribute("MoraleGod"));
		player:SetAttribute("LineID", BattlePermissions:GetPublicLineID());
		player:SetAttribute("TargetWalkSpeed", StarterPlayer.CharacterWalkSpeed);
		player:SetAttribute("Loadout", "Ranker");

		player.Changed:Connect(function(property)
			if property == "Team" then
				local torso = player.Character:FindFirstChild("Torso")
				if torso then
					player.Character.Torso:SetAttribute("TeamColor", player.TeamColor);
				end
			end
		end)

		if ModeratorLogs:IsPlayerModerator(player) and game.PrivateServerOwnerId == 0 and not RunService:IsStudio() then
			ModeratorLogs:RegisterModeratorOnline(player);
		end

		if game.PrivateServerOwnerId ~= 0 then
			CommonFunctions:AwardBadge(player, 2725277510082941, false);
		end

		coroutine.wrap(function()
			while true do
				task.wait(60);

				local profile = ProfileManager.Profiles[player];
				if profile then
					profile.Data.Playtime += 1;

					local playerGroupRank = player:GetRankInGroup(33078943);
					if playerGroupRank > 0 and playerGroupRank < 2 then
						if profile.Data.Playtime >= script:GetAttribute("HoursForEpicSupporter") * 60 and playerGroupRank ~= 2 then
							RankGunRanking:SetRank(player.Name, 2);
						end
					end
				end
			end
		end)()

		RespawnPlayer:Fire(player);
	end
end

