TeleportToSpawn.OnServerInvoke = function(player, spawnLocation)
	AntiExploitImmunity:RevokePlayerImmunity(player);

	local passed = RemoteSecurity:PassedRemoteSecurity(TeleportToSpawn, player, 3, {spawnLocation}, {"Instance"});
	if passed then
		if not player:GetAttribute("Spawned") then
			if spawnLocation and spawnLocation:IsA("BasePart") then
				if not ReplicatedStorage:GetAttribute("BattleStarting") then
					if ReplicatedStorage:GetAttribute("BattleStarted") and ReplicatedStorage:GetAttribute(player.Team.Name.."Tickets") == 0 then
						return "Team out of tickets";
					end
					if SharedTechFunctions:IsDescendantOfAnyCharacter(spawnLocation) and player:GetAttribute("Loadout") == "Flag Bearer" then
						if not PlayerClasses:FlagBearerCanSpawnOnFlag(player) then
							return "Flag cannot spawn on flag";
						end
					end
					if not player.Character or not player.Character.PrimaryPart then
						return "Character not found";
					end

					local validMessage = SpawnLocations:SpawnLocationIsValidForPlayer(spawnLocation, player);
					if typeof(validMessage) == "boolean" then
						AntiExploitImmunity:GivePlayerImmunity(player, 1);
						player:SetAttribute("Spawned", true);
						AdjustCharacterHumanoid(player, player.Character);

						local newCFrame = spawnLocation.CFrame * CFrame.new(0, 4, 0);
						TeleportCharacter(player.Character, newCFrame);

						PlayerClasses:GivePlayerLoadout(player);

						coroutine.wrap(function()
							while player:GetAttribute("Spawned") do
								if player.Character then
									if player:GetAttribute("Spawned") then
										if (player.Character.PrimaryPart.Position - Map.Lobby.SpawnLocation.Position).Magnitude <= 200 then
											RespawnPlayer:Fire(player);
										end
									end
								end
								task.wait(1);
							end
						end)()

						CreateCharacterPart(player, player.Character, ForceFieldEffect, Vector3.new(0, -0.4, 0));
						if player.Backpack:FindFirstChild("Flag") and player.Character:FindFirstChild("Humanoid") then
							player.Character.Humanoid:EquipTool(player.Backpack.Flag);
						end

						return true;
					end
					return validMessage;
				end
				return "Battle is starting";
			end
			return "Invalid spawn???";
		end
		return "Already spawned???";
	end
	return "Attempting too fast";
end
