PlaceStructure.OnServerInvoke = function(player, clientStructureName, clientStructureCFrame, mousePosition)
	local passed = RemoteSecurity:PassedRemoteSecurity(PlaceStructure, player, 1, {clientStructureName, clientStructureCFrame, mousePosition}, {"string", "CFrame", "Vector3"});
	if passed then
		if player.Character:FindFirstChild("Hammer") then
			local realStructure = SavedStructures:FindFirstChild(clientStructureName);
			if realStructure then
				if typeof(SharedTechFunctions:IsSapperPlacementGood(player.Character.Torso, mousePosition)) == "boolean" then
					if math.abs(clientStructureCFrame.Position.X - mousePosition.X) <= 0.1 and math.abs(clientStructureCFrame.Position.Y - mousePosition.Y) <= 0.1 and math.abs(clientStructureCFrame.Position.Z - mousePosition.Z) <= 0.1 then
						if realStructure.Name == "Fort" then
							if PlayerAlreadyHasFort(player) then
								return "Already built fort";
							end
							if FortIsNearAnotherFort(clientStructureCFrame.Position) then
								return "Near another fort";
							end
						end
						if realStructure:GetAttribute("RequiresFort") then
							if not StructureIsNearFort(clientStructureCFrame.Position, player.TeamColor) then
								return "Requires fort nearby";
							end
						end
						if player:GetAttribute("Materials") >= realStructure:GetAttribute("Cost") then
							player:SetAttribute("Materials", player:GetAttribute("Materials") - realStructure:GetAttribute("Cost"));
							local structureToPlace = realStructure:Clone();
							structureToPlace:SetPrimaryPartCFrame(clientStructureCFrame);
							structureToPlace:SetAttribute("OwnerName", player.Name);
							structureToPlace:SetAttribute("TeamColor", player.TeamColor);
							structureToPlace.Parent = workspace.Structures;
							return true;
						end
						return "Not enough materials";
					end
					return "Bad placement match";
				end
				return "Bad placement location";
			end
			return "Structure doesn't exist";
		end
		return "No hammer found";
	end
	return "Placing too frequently";
end
