Whitelist.OnInvoke = function(action, groupInfo)
	if action == "add" then
		if not table.find(WhitelistedGroups, groupInfo.Id) then
			table.insert(WhitelistedGroups, groupInfo.Id);
			return "Added group "..groupInfo.Name.." to the whitelist";
		end
		return "Unable to change whitelist, that group is already on the whitelist.";
	elseif action == "remove" then
		local index = table.find(WhitelistedGroups, groupInfo.Id);
		if index then
			table.remove(WhitelistedGroups, index);
			return "Removed group "..groupInfo.Name.." from the whitelist";
		end
		return "Unable to change whitelist, that group is already off the whitelist.";
	elseif action == "clear" then
		if #WhitelistedGroups > 0 then
			for index, groupID in pairs(WhitelistedGroups) do
				table.remove(WhitelistedGroups, index);
			end
			return "Cleared the whitelist of all groups.";
		end
		return "Unable to change whitelist, whitelist is already cleared.";
	end
end
ServerLock.OnInvoke = function(action)
	if action == "lock" then
		if not ServerLocked then
			ServerLocked = true;
			return "Locked the server.";
		end
		return "Unable to lock server, server is already locked.";
	elseif action == "unlock" then
		if ServerLocked then
			ServerLocked = false;
			return "Unlocked the server.";
		end
		return "Unable to unlock server, server is already unlocked.";
	end
end

