-- Functions --
local function ToggleCharacterAnchors(toggle)
	for each, player in pairs(Players:GetPlayers()) do
		local character = player.Character;
		if character and player:GetAttribute("Spawned") then
			local torso = character:FindFirstChild("Torso");
			if torso then
				torso.Anchored = toggle;
			end
		end
	end
end
local function GetLineStats(allLineMembers, botRegiment)
	local strength, maxStrength, morale, maxMorale = 0, 0, 0, 0;

	for each, member in pairs(allLineMembers) do
		local humanoid = member:FindFirstChild("Humanoid");
		if botRegiment and humanoid then
			strength += humanoid.Health;
			morale += member:GetAttribute("Morale");
		else
			local player = Players:GetPlayerFromCharacter(member);
			if humanoid and player and player:GetAttribute("Morale") then
				if player:GetAttribute("Spawned") then
					strength += humanoid.Health;
					morale += player:GetAttribute("Morale");
				end
				maxStrength += humanoid.MaxHealth;
				maxMorale += PlayerSettings.MoraleMaximum;
			end
		end
	end

	if botRegiment then
		maxStrength += 100 * botRegiment:GetAttribute("MaxMembers");
		maxMorale += PlayerSettings.MoraleMaximum* botRegiment:GetAttribute("MaxMembers");
	end

	return strength, maxStrength, morale, maxMorale;
end
local function GetAveragePosition(positions)
	if #positions > 0 then
		local averageX, averageY, averageZ = 0, 0, 0;
		for each, position in pairs(positions) do
			averageX += position.X;
			averageY += position.Y;
			averageZ += position.Z;
		end
		averageX /= #positions;
		averageY /= #positions;
		averageZ /= #positions;
		return Vector3.new(averageX, averageY, averageZ);
	end
	return nil;
end
local function UpdateLineStatus(overhead, status)
	if overhead:FindFirstChild("IconGui") and overhead.IconGui.Status.Text ~= status then
		overhead.IconGui.Status.Text = status;

		if CurrentStatusTween then
			CurrentStatusTween:Cancel();
		end

		coroutine.wrap(function()
			while overhead:FindFirstChild("IconGui") and overhead.IconGui.Status.Text == status do
				if overhead:FindFirstChild("IconGui") then
					CurrentStatusTween = TweenService:Create(overhead.IconGui.Status, TweenInfo.new(1), {TextColor3 = StatusColors[status]});
					CurrentStatusTween:Play();
					CurrentStatusTween.Completed:Wait();
				else
					break;
				end
				if overhead:FindFirstChild("IconGui") then
					CurrentStatusTween = TweenService:Create(overhead.IconGui.Status, TweenInfo.new(1), {TextColor3 = Color3.fromRGB(255, 255, 255)});
					CurrentStatusTween:Play();
					CurrentStatusTween.Completed:Wait();
				else
					break;
				end
				task.wait();
			end
		end)()
	end
end
local function PositionLineOverheads()
	for each, overhead in pairs(workspace.Overheads:GetChildren()) do
		local allLineMembers = {};
		local lineMembers = {};
		local rawMemberPositions = {};
		local memberPositions = {};
		local leaderPosition;
		local flagBearerPosition;
		local regiment;

		if overhead:GetAttribute("BotRegiment") then
			for each, otherRegiment in pairs(workspace.Bots.Regiments:GetChildren()) do
				if otherRegiment:GetAttribute("LineID") == overhead:GetAttribute("LineID") then
					regiment = otherRegiment;
					break;
				end
			end

			if regiment then
				for each, bot in pairs(regiment.Members:GetChildren()) do
					table.insert(lineMembers, bot);

					if bot:GetAttribute("Officer") then
						if bot:FindFirstChild("Torso") and bot:FindFirstChild("Humanoid") and bot.Humanoid.Health > 0 then
							leaderPosition = bot.Torso.Position;
						end
					end

					if bot:FindFirstChild("Flag") and not bot.Flag:GetAttribute("UnderCapture") then
						if bot:FindFirstChild("Torso") and bot:FindFirstChild("Humanoid") and bot.Humanoid.Health > 0 then
							flagBearerPosition = bot.Torso.Position;
						end
					end

					table.insert(allLineMembers, bot);
				end

				if #allLineMembers < PlayerSettings.LineMembersNeededForOverhead then
					overhead:Destroy();
				end
			else
				overhead:Destroy();
			end
		else
			for each, character in pairs(workspace:GetChildren()) do
				local player = Players:GetPlayerFromCharacter(character);
				if player and player:GetAttribute("LineID") == overhead:GetAttribute("LineID") then
					if player:GetAttribute("Spawned") then
						table.insert(lineMembers, character);

						if player:GetAttribute("LineOwnerName") == player.Name then
							if character:FindFirstChild("Torso") and character:FindFirstChild("Humanoid") and character.Humanoid.Health > 0 then
								leaderPosition = character.Torso.Position;
							end
						end

						if character:FindFirstChild("Flag") and not character.Flag:GetAttribute("UnderCapture") then
							if character:FindFirstChild("Torso") and character:FindFirstChild("Humanoid") and character.Humanoid.Health > 0 then
								flagBearerPosition = character.Torso.Position;
							end
						end
					end
					table.insert(allLineMembers, character);
				end
			end
		end

		if #lineMembers == 0 then
			overhead:Destroy();
		else
			for each, member in pairs(lineMembers) do
				if member:FindFirstChild("Torso") then
					if member.Torso.Position.Y > -15 and member:FindFirstChild("Humanoid") and member.Humanoid.Health > 0 then
						table.insert(rawMemberPositions, member.Torso.Position);
					end
				end
			end

			local rawAveragePosition = GetAveragePosition(rawMemberPositions);
			if rawAveragePosition then
				for each, member in pairs(lineMembers) do
					if member:FindFirstChild("Torso") and member:FindFirstChild("Humanoid") and member.Humanoid.Health > 0 then
						if (member.Torso.Position - rawAveragePosition).Magnitude <= 75 then
							table.insert(memberPositions, member.Torso.Position);
						end
					end
				end
			end

			local status = "";
			local averagePosition = GetAveragePosition(memberPositions); --Stay over where the majority of members are
			if #memberPositions >= math.floor(#allLineMembers / 2) then
				status = "";
			elseif flagBearerPosition then
				averagePosition = flagBearerPosition; --If there is no majority alive, stay over the flag bearer
				status = "DISORGANIZED";
			elseif leaderPosition then
				averagePosition = leaderPosition; --If there is no majority or flag active, stay over the line leader
				status = "BROKEN";
			elseif not averagePosition then
				averagePosition = Vector3.new(overhead.Position.X, overhead.Position.Y - 30, overhead.Position.Z); --If no one is alive, stay in place
				status = "SHATTERED";
			end

			if averagePosition then
				overhead.Position = Vector3.new(averagePosition.X, averagePosition.Y + 30, averagePosition.Z);
			end
			for each, spawnPad in pairs(workspace.Map.Spawns:GetChildren()) do
				if spawnPad.Name ~= overhead:GetAttribute("LineTeamName") and (overhead.Position - spawnPad.Position).Magnitude <= PlayerSettings.MoraleDistanceForSpawn then
					status = "SPAWN CAMPING";
				end
			end
			UpdateLineStatus(overhead, status);

			if overhead:GetAttribute("BotRegiment") and overhead:FindFirstChild("IconGui") then
				local strength, maxStrength, morale, maxMorale = GetLineStats(allLineMembers, regiment);
				overhead.IconGui.Health.Bar.Size = UDim2.new(strength / maxStrength, 0, 1, 0);
				overhead.IconGui.Morale.Bar.Size = UDim2.new(morale / maxMorale, 0, 1, 0);
				overhead.IconGui.Line.Text = regiment:GetAttribute("LineName");
				overhead.IconGui.Icon.Image = regiment:GetAttribute("LineIcon");
			else
				local lineName, lineIcon, lineTeamName = BattlePermissions:GetLineInfoFromID(overhead:GetAttribute("LineID"));
				if lineName then
					local strength, maxStrength, morale, maxMorale = GetLineStats(allLineMembers, nil);
					overhead.IconGui.Health.Bar.Size = UDim2.new(strength / maxStrength, 0, 1, 0);
					overhead.IconGui.Morale.Bar.Size = UDim2.new(morale / maxMorale, 0, 1, 0);
					overhead.IconGui.Line.Text = lineName;
					overhead.IconGui.Icon.Image = lineIcon;
				else
					overhead:Destroy();
				end
			end
		end
	end
end
local function UpdateLineOverheads()
	local activeLines = {};

	for each, player in pairs(Players:GetPlayers()) do
		if player:GetAttribute("LineID") and player:GetAttribute("LineID") ~= BattlePermissions:GetPublicLineID() then
			if not activeLines[player:GetAttribute("LineID")] then
				activeLines[player:GetAttribute("LineID")] = 1;
			else
				activeLines[player:GetAttribute("LineID")] += 1;
			end
		end
	end

	for lineID, lineCount in pairs(activeLines) do
		if lineCount >= PlayerSettings.LineMembersNeededForOverhead then
			local alreadyCreated = false;
			for each, overhead in pairs(workspace.Overheads:GetChildren()) do
				if overhead:GetAttribute("LineID") == lineID then
					alreadyCreated = true;
					break;
				end
			end
			if not alreadyCreated then
				local lineName, lineIcon, lineTeamName = BattlePermissions:GetLineInfoFromID(lineID);
				if lineName then
					local overheadPart = LineOverheadTemplate:Clone();
					overheadPart.IconGui.Line.Text = lineName;
					overheadPart.IconGui.Icon.Image = lineIcon;
					overheadPart:SetAttribute("LineID", lineID);
					overheadPart:SetAttribute("LineTeamName", lineTeamName);
					overheadPart.Parent = workspace.Overheads;
				end
			end
		else
			for each, overhead in pairs(workspace.Overheads:GetChildren()) do
				if overhead:GetAttribute("LineID") == lineID then
					overhead:Destroy();
				end
			end
		end
	end
end

local function LineOverheadLoop()
	coroutine.wrap(function()
		while true do
			UpdateLineOverheads();
			PositionLineOverheads();
			task.wait(0.05);
		end
	end)()
end
LineOverheadLoop();

