Battle.OnInvoke = function(action, executorName)
	if action == "start" then
		if ReplicatedStorage:GetAttribute("BattleEnded") and not ReplicatedStorage:GetAttribute("BattleStarting") then
			if ReplicatedStorage:GetAttribute("BattleMinutes") >= 2 then
				script:SetAttribute("HealthGod", true);
				script:SetAttribute("MoraleGod", true);
				ReplicatedStorage:SetAttribute("BattleEnded", false);
				ReplicatedStorage:SetAttribute("BattleStarting", true);
				EventToClient:FireAllClients("NotifyBattle", {"start", executorName});
				return "Started the battle.";
			end
			return "Unable to change battle, cannot start a battle with less than 2 minutes on the timer.";
		end
		return "Unable to change battle, cannot start a battle that's already started or is starting/ending.";
	elseif action == "end" then
		if ReplicatedStorage:GetAttribute("BattleStarted") and not ReplicatedStorage:GetAttribute("BattleEnding") then
			ReplicatedStorage:SetAttribute("BattleMinutes", 1);
			ReplicatedStorage:SetAttribute("BattleSeconds", 1);
			EventToClient:FireAllClients("NotifyBattle", {"end", executorName});
			return "Ended the battle.";
		end
		return "Unable to change battle, cannot end a battle that's already ended or is starting/ending.";
	elseif action == "reset" then
		if ReplicatedStorage:GetAttribute("BattleEnded") then
			for each, player in pairs(Players:GetPlayers()) do
				if player.Character then
					RespawnPlayer:Fire(player);
				end
			end
			ReplicatedStorage:SetAttribute("Team1Tickets", 10000);
			ReplicatedStorage:SetAttribute("Team2Tickets", 10000);
			ReplicatedStorage:SetAttribute("BattleMinutes", 45);
			ReplicatedStorage:SetAttribute("BattleSeconds", 0);
			return "Reset the battle.";
		end
		return "Unable to change battle, cannot reset a battle that's not ended.";
	end
end
God.OnInvoke = function(godType, executorName)
	if godType == "health" then
		script:SetAttribute("HealthGod", not script:GetAttribute("HealthGod"));
		EventToClient:FireAllClients("NotifyGod", {"health", executorName});
