	elseif godType == "morale" then
		script:SetAttribute("MoraleGod", not script:GetAttribute("MoraleGod"));
		EventToClient:FireAllClients("NotifyGod", {"morale", executorName});
		return "Toggled morale god for all players.";
	end
end

-- Permissions Events --
LineAction.OnServerInvoke = function(player, action, newString)
	local passed = RemoteSecurity:PassedRemoteSecurity(LineAction, player, 1, {action, newString}, {"string", "string"});
	if passed then
		if action ~= "AcceptInvite" and action ~= "RejectInvite" and action ~= "RemoveSelf" and action ~= "JoinPublic" then
			if (game.PrivateServerOwnerId ~= 0 or RunService:IsStudio()) and not BattlePermissions:GetPlayerPermissions(player) then
				return "Insufficient permissions";
			end
			if not player:GetAttribute("OwnsLineCreation") then
				return "Line pass not owned";
			end

			if action == "Create" then
				return BattlePermissions:CreateLine(player);
			elseif action == "Delete" then
				return BattlePermissions:DeleteLine(player);
			elseif action == "Name" then
				return BattlePermissions:UpdateLine(player, newString, nil);
			elseif action == "Icon" then
				if player:GetAttribute("OwnsCustomFlag") then
					return BattlePermissions:UpdateLine(player, nil, newString);
				end
				return "Flag pass not owned";
			elseif action == "Invite" then
				return BattlePermissions:InvitePlayerToLine(newString, player);
			elseif action == "Remove" then
				return BattlePermissions:RemovePlayerFromLine(newString, player); --security concern, mass removal???
			elseif action == "Public" then
				return BattlePermissions:UpdateLineAccess("Public", player);
			elseif action == "Private" then
				return BattlePermissions:UpdateLineAccess("Private", player);
			elseif action == "DropFlag" then
				return BattlePermissions:DropAllFlagsInLine(player);
			end
		else
			if action == "RemoveSelf" then
				return BattlePermissions:RemovePlayerFromLine(player.Name, player);
			elseif action == "AcceptInvite" then
				return BattlePermissions:AcceptLineInvite(player, newString);
			elseif action == "RejectInvite" then
				return BattlePermissions:RejectLineInvite(player, newString);
			elseif action == "JoinPublic" then
				return BattlePermissions:JoinPublicLine(player, newString);
			end
		end
		return "Invalid action";
	end
	return "Updating too fast";
end

