-- Functions --
local function GetBotDistanceToWaypoint(waypoint)
	if waypoint == Post then
		return (HumanoidRootPart.Position - Vector3.new(Post.Position.X, HumanoidRootPart.Position.Y, Post.Position.Z)).Magnitude;
	end
	return (HumanoidRootPart.Position - waypoint).Magnitude;
end
local function GetDelayWithDifficulty(delayType)
	if Regiment:GetAttribute("Difficulty") == 0 then
		return delayType == "End" and RNG:NextNumber(0, 0.5) or RNG:NextNumber(0, 1.5);
	elseif Regiment:GetAttribute("Difficulty") == 1 then
		return delayType == "End" and RNG:NextNumber(0, 0.25) or RNG:NextNumber(0, 0.5);
	end
end
local function GetRandomTargetPosition()
	local validEnemies = {};

	if ClosestEnemy and ClosestEnemy:FindFirstChild("Members") then
		for each, enemy in pairs(ClosestEnemy.Members:GetChildren()) do
			if enemy:FindFirstChild("HumanoidRootPart") and enemy:FindFirstChild("Humanoid") then
				if enemy.Humanoid.Health > 0 and (enemy.HumanoidRootPart.Position - HumanoidRootPart.Position).Magnitude <= Settings.WeaponMaximumRange then
					table.insert(validEnemies, enemy);
				end
			end
		end
	end

	Target = #validEnemies > 0 and validEnemies[RNG:NextInteger(1, #validEnemies)] or nil;
	AimPosition = Target and Target.HumanoidRootPart.Position or Vector3.new(0, 0, 0);
end
local function GetPostFromPosition(position)
	for each, post in pairs(Formation:GetChildren()) do
		if post:GetAttribute("PositionFromCenter") == position then
			return post;
		end
	end
end
local function DoCommandSpecificFunction(commandType, command)
	if commandType == "Start" then
		if command == "Present" then
			GetRandomTargetPosition();
		end
	elseif commandType == "End" then
		if command == "Fire" then
			Target = nil;
			AimPosition = Vector3.new(0, 0, 0);
		end
	end
end
local function ProcessCommand(command, idleStart, movement, idleEnd, eventData)
	DoCommandSpecificFunction("Start", command);
	task.wait(GetDelayWithDifficulty("Start"));

	while Bot:GetAttribute("Command") == command do
		if Settings.ToolStance == idleStart then
			ToolEvent:Fire(eventData);
		elseif Settings.ToolStance == movement then
			repeat task.wait(0.1); until tostring(Settings.ToolStance) == idleEnd or Bot:GetAttribute("Command") ~= command;

			DoCommandSpecificFunction("End", command);
			task.wait(GetDelayWithDifficulty("End"));

			Bot:SetAttribute("Command", Bot:GetAttribute("Command") == command and "" or Bot:GetAttribute("Command"));
		end
		task.wait();
	end
end
local function GetNewPathToWaypoint(destination)
	local success, errorMessage = pcall(function()
		Path:ComputeAsync(Bot.PrimaryPart.Position, destination);
	end)

	if success and Path.Status == Enum.PathStatus.Success then
		local waypoints = Path:GetWaypoints();
		local nextWaypointIndex = 2;
		local blockedConnection;
		local reachedConnection;

		blockedConnection = Path.Blocked:Connect(function(blockedWaypointIndex)
			if blockedWaypointIndex >= nextWaypointIndex then
				blockedConnection:Disconnect();
				GetNewPathToWaypoint(destination.Position);
			end
		end)

		for i = 2, #waypoints do
			nextWaypointIndex = i;
			repeat
				Humanoid:Move(CFrame.lookAt(HumanoidRootPart.Position, waypoints[nextWaypointIndex].Position).LookVector);
				task.wait();
			until GetBotDistanceToWaypoint(waypoints[nextWaypointIndex].Position) <= 10;
		end
	else
		warn("Path not computed!", errorMessage);
	end
end

-- Loops --
local function DoFillGapsLoop()
	coroutine.wrap(function()
		while true do
			if Bot:GetAttribute("Positioned") then
				local postToShiftTo;
				if Post:GetAttribute("PositionFromCenter") > 0 then
					postToShiftTo = GetPostFromPosition(Post:GetAttribute("PositionFromCenter") - 1);
				elseif Post:GetAttribute("PositionFromCenter") < 0 then
					postToShiftTo = GetPostFromPosition(Post:GetAttribute("PositionFromCenter") + 1);
				end
				if postToShiftTo then
					local botOnPost = postToShiftTo.BotOnPost.Value;
					if not botOnPost or not botOnPost:IsDescendantOf(workspace) then
						postToShiftTo.BotOnPost.Value = Bot;
						Post = postToShiftTo;
					end
				end
			end
			task.wait();
		end
	end)()
end
local function DoMovementLoop()
	coroutine.wrap(function()
		while true do
			if Post:IsDescendantOf(workspace) and GetBotDistanceToWaypoint(Post) > 1 then
				Bot:SetAttribute("Positioned", false);
				GetNewPathToWaypoint(Post.Position);
				Bot:SetAttribute("Positioned", true);
				Humanoid:Move(Vector3.new(0, 0, 0));
			elseif Post:IsDescendantOf(workspace) then
				Bot:SetAttribute("Positioned", true);
				Humanoid:Move(Vector3.new(0, 0, 0));
			else
				Bot:Destroy();
			end
			task.wait();
		end
	end)()
end
local function DoDirectionLoop()
	coroutine.wrap(function()
		while true do
			if Bot:GetAttribute("Positioned") and AimPosition == Vector3.new(0, 0, 0) and Post:IsDescendantOf(workspace) then
				HumanoidRootPart.CFrame = CFrame.new(HumanoidRootPart.Position, Vector3.new(Post.Front.Position.X, HumanoidRootPart.Position.Y, Post.Front.Position.Z));
			end
			task.wait();
		end
	end)()
end
local function DoSlopeArmsManuever()
	coroutine.wrap(function()
		while true do
			if Regiment:GetAttribute("Difficulty") >= 1 then
				if not Bot:GetAttribute("Positioned") and GetBotDistanceToWaypoint(Post) > 100 then
					if Settings.ToolStance == "[I] Shouldered Arms" then
						ToolEvent:Fire({Vector3.new(0, 0, 0), Enum.UserInputType.Keyboard, Enum.KeyCode.K});
					end
				elseif Settings.ToolStance == "[I] Trailed Arms" then
					ToolEvent:Fire({Vector3.new(0, 0, 0), Enum.UserInputType.Keyboard, Enum.KeyCode.K});
				end
			end
			task.wait();
		end
	end)()
end
local function DoAimLoop()
	coroutine.wrap(function()
		while true do
			if Target and Target:FindFirstChild("HumanoidRootPart") then
				AimPosition = Target.HumanoidRootPart.Position;
			else
				Target = nil;
				AimPosition = Vector3.new(0, 0, 0);
			end
			task.wait();
		end
	end)()
end

