local function CharacterAdded(player, character)
	local roleInColonialBritishArmy = player:GetRoleInGroup(8047501);
	local roleIn7thRegiment = player:GetRoleInGroup(33712250);
	local humanoid = character:WaitForChild("Humanoid");

	if roleInColonialBritishArmy ~= "Guest" then
		local foundUniform = false;
		for each, uniform in pairs(script:GetDescendants()) do
			if uniform:GetAttribute("CBA") == roleInColonialBritishArmy and uniform:GetAttribute("7th") == roleIn7thRegiment then
				uniform:Clone().Parent = character;
				foundUniform = true;
			end
		end

		if foundUniform then
			script.BritishRegularTricorn:Clone().Parent = character;

			task.spawn(function()
				local noRemovals = 0;
				while humanoid.Health > 0 do
					local removed = 0;

					for each, thing in pairs(character:GetChildren()) do
						if not thing:GetAttribute("Custom") then
							if thing:IsA("Shirt") or thing:IsA("Pants") or thing:IsA("ShirtGraphic") or thing:IsA("CharacterMesh") then
								thing:Destroy();
								removed += 1;
							elseif thing:IsA("Accessory") and thing.AccessoryType ~= Enum.AccessoryType.Hair then
								thing:Destroy();
								removed += 1;
							end
						end
					end

					if removed == 0 then
						noRemovals += 1;
						if noRemovals == 5 then
							break;
						end
					end

					task.wait(1);
				end
			end)
		end
	end
end

local function PlayerAdded(player)
	if player.Character then
		CharacterAdded(player, player.Character);
	else
		player.CharacterAdded:Connect(function(character)
			CharacterAdded(player, character)
		end)
	end
end

