			if string.sub(keyframeName, 1, 2) == "[[" then
				Settings.BodyStance = keyframeName;
			else
				Settings.ToolStance = keyframeName;
			end
		end)
		animationTrack:GetMarkerReachedSignal("TTV"):Connect(function()
			ServerTechFunctions:ToggleToolVisibility(true, ToolFolder);
			ServerTechFunctions:ToggleHolsterDisplay(false, Character, Tool);
		end)
		animationTrack:GetMarkerReachedSignal("PlaySound"):Connect(function(soundNames)
			ServerTechFunctions:PlaySound(soundNames, Sounds, BodyAttach);
		end)
		animationTrack:GetMarkerReachedSignal("Healed"):Connect(function()
			if Settings.HealActive then
				Settings.HealActive = false;

				local newWounds = math.clamp(Settings.HealTarget:GetAttribute("BleedingWounds") - Settings.WoundsRemovedPerHeal, 0, math.huge);
				Settings.HealTarget:SetAttribute("BleedingWounds", newWounds);
				if newWounds == 0 then
					Settings.HealTarget:SetAttribute("Bleeding", false);
				end

				local newMorale = math.clamp(Player:GetAttribute("Morale") + Settings.MoraleRecoveredPerHeal, 0, PlayerSettings.MoraleMaximum);
				Player:SetAttribute("Morale", newMorale);
				Settings.HealTarget.Humanoid.Health += Settings.HealthRecoveredPerHeal;
				Settings.HealTarget:SetAttribute("Healing", false);
				Settings.HealTarget = nil;
				Settings.HealsRemaining -= 1;
				if Settings.HealsRemaining == 0 then
					Humanoid:UnequipTools();
					Character.BandageDisplay:Destroy();
					ServerTechFunctions:DisableAnimationsIfNotEquipped(Tool, AnimationTracks);
					Tool:Destroy();
				end
			end
		end)
	end
