-- Animation Functions --
local function CreateAnimationTracks()
	if not Character:IsDescendantOf(workspace) then
		repeat task.wait(0.1); until Character:IsDescendantOf(workspace);
	end
	AnimationObjects, AnimationTracks = ServerTechFunctions:CreateAnimationTracks(Animations, Humanoid);

	for each, animationTrack in pairs(AnimationTracks) do
		animationTrack.KeyframeReached:Connect(function(keyframeName)
			if string.sub(keyframeName, 1, 2) == "[[" then
				Settings.BodyStance = keyframeName;
			else
				Settings.ToolStance = keyframeName;
			end
		end)
		animationTrack:GetMarkerReachedSignal("TTV"):Connect(function()
			ServerTechFunctions:ToggleToolVisibility(true, ToolFolder);
			ServerTechFunctions:ToggleHolsterDisplay(false, Character, Tool);
		end)
		animationTrack:GetMarkerReachedSignal("PlaySound"):Connect(function(soundNames)
			ServerTechFunctions:PlaySound(soundNames, Sounds, BodyAttach);
		end)
		animationTrack:GetMarkerReachedSignal("Melee"):Connect(function(status)
			if status == "enabled" then
				Settings.MeleeActive = true;
				while Settings.MeleeActive do
					Settings.MeleeActive = ServerTechFunctions:FindTargetToMelee(Tool.Name, ToolHitbox, Player, Character, Head, CharacterHitbox, Settings.MeleeStabDamage, Settings.MeleeStabStructureDamage, Settings.MeleeBashDamage, Settings.MeleeBashStructureDamage, Settings.ToolStance, Settings.MaximumMeleeAngle, Sounds, BodyAttach);
					task.wait(0.1);
				end
			elseif status == "disabled" then
				Settings.MeleeActive = false;
			end
		end)
		animationTrack:GetMarkerReachedSignal("MeleeAiming"):Connect(function(status)
			if status == "enabled" then
				Tool:SetAttribute("MeleeAiming", true);
			elseif status == "disabled" then
				Tool:SetAttribute("MeleeAiming", false);
			end
		end)
		animationTrack:GetMarkerReachedSignal("Chop"):Connect(function()
			if Settings.ChopActive then
				local treeParts = workspace:GetPartsInPart(ToolHitbox, ChopParams);
				if treeParts then
					for each, part in pairs(treeParts) do
						if part.Name == "TreeHitbox" then
							ServerTechFunctions:PlaySound("Chop", Sounds, BodyAttach);
							Player:SetAttribute("Materials", Player:GetAttribute("Materials") + RNG:NextInteger(1, 3));
							break;
						end
					end
				end
			end
		end)
	end
end

