								while Tool:GetAttribute("Mouse1Held") do
									task.wait();
								end
								if Settings.MeleePlaying then
									ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Melee "..dataTable[3].." Push"], AnimationTracks["[I] Meleed Arms"], "[", AnimationTracks, AnimationObjects);
								end
							elseif dataTable[2] == "BlockMelee" then
								ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Melee "..dataTable[3].." Block"], AnimationTracks["[I] Melee "..dataTable[3].." Blocked"], "[", AnimationTracks, AnimationObjects);
								task.wait(AnimationObjects["[M] Melee "..dataTable[3].." Block"]:GetAttribute("AnimationSpeed") - 0.1);
								while Tool:GetAttribute("Mouse2Held") do
									task.wait();
								end
								if Settings.MeleePlaying then
									ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Melee "..dataTable[3].." Unblock"], AnimationTracks["[I] Meleed Arms"], "[", AnimationTracks, AnimationObjects);
								end
							end

							Settings.MeleePlaying = false;
						end
					end
				end
			elseif dataTable[2] == "Mouse1Held" then
				if typeof(dataTable[3]) == "boolean" then
					Tool:SetAttribute("Mouse1Held", dataTable[3]);
					if Tool:GetAttribute("Mouse1Held") and Settings.ToolStance == "[I] Equipped" then
						Settings.ChopActive = true;
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Chop"], AnimationTracks["[I] Chopping"], "[", AnimationTracks, AnimationObjects);
					elseif Settings.ChopActive then
						Settings.ChopActive = false;
						task.wait(0.2);
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] ChopEnd"], AnimationTracks["[I] Equipped"], "[", AnimationTracks, AnimationObjects);
					end
				end
			elseif dataTable[2] == "Mouse2Held" then
				if typeof(dataTable[3]) == "boolean" then
					Tool:SetAttribute("Mouse2Held", dataTable[3]);
				end
			end
		elseif typeof(dataTable[2]) == "EnumItem" and typeof(dataTable[3]) == "EnumItem" then
			if dataTable[3] == Settings.CrouchKey then
				if Settings.BodyStance == "[[I]] Stood" then
					TweenService:Create(RootJoint, CrouchTweenInfo, {C0 = CFrame.new(0, -1.161, 0) * CrouchAngle}):Play();
					ServerTechFunctions:PlayAnimations(AnimationTracks["[[M]] Crouch"], AnimationTracks["[[I]] Crouched"], "[[", AnimationTracks, AnimationObjects);
