-- Terrain Functions --
local function AttemptToDigAtPosition(digPosition)
	if (digPosition - Torso.Position).Magnitude <= PlayerSettings.PlaceDistance then
		if digPosition.Y <= PlayerSettings.MaximumHeightLimit and digPosition.Y >= PlayerSettings.MinimumHeightLimit then
			local passedSpawnPadCheck = true;

			for each, spawnPad in pairs(workspace.Map.Spawns:GetChildren()) do
				if (spawnPad.Position - digPosition).Magnitude <= PlayerSettings.SpawnPadPlaceDistance then
					passedSpawnPadCheck = false;
					break;
				end
			end

			if passedSpawnPadCheck then
				Player:SetAttribute("Materials", Player:GetAttribute("Materials") + RNG:NextInteger(2, 5));
				workspace.Terrain:FillBall(digPosition, 4, Enum.Material.Air);
				workspace.Terrain:ReplaceMaterial(Region3.new(Vector3.new(digPosition.X - 5, digPosition.Y - 5, digPosition.Z - 5), Vector3.new(digPosition.X + 5, digPosition.Y - 4, digPosition.Z + 5)), 4, Enum.Material.Grass, Enum.Material.Ground);
				return true;
			end
			return "Too close to spawn";
		end
		return "Beyond height limit";
	end
	return "Too far away";
end

