					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Support Arms"], AnimationTracks["[I] Supported Arms"], "[", AnimationTracks, AnimationObjects);
				elseif Settings.ToolStance == "[I] Supported Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Unsupport Arms"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
