-- Initial Function --
local function Initialize()
	debug.setmemorycategory("Script_BlunderbussServer");

	Tool6D.Name = "Blunderbuss6D";
	Tool6D:SetAttribute("ActiveTool6D", false);
	Tool6D.Parent = Torso;

	if Settings.VisualizeHitbox and Settings.DebugEnabled then
		Hitbox.Transparency = 0.9;
	end

	ServerTechFunctions:ToggleHolsterDisplay(true, Character, Tool);

	FireEffects = ServerTechFunctions:AssembleFireEffects(ToolFolder);
	CreateAnimationTracks();

	if Player:GetAttribute(Tool.Name.."Loaded") == nil then
		Player:SetAttribute(Tool.Name.."Loaded", true);
	end

	Settings.Initialized = true;
end
Initialize();

