-- Flag Functions --
local function UpdateSpawnBlocking()
	local nearbyEnemies = 0;

	for each, character in pairs(workspace:GetChildren()) do
		local player = Players:GetPlayerFromCharacter(character);
		if player and player.Team ~= Player.Team and character:FindFirstChild("Torso") then
			if character.Humanoid.Health > 0 then
				if (character.Torso.Position - Torso.Position).Magnitude <= PlayerSettings.EnemyDistanceToBlockFlag then
					nearbyEnemies += 1;
					if nearbyEnemies == PlayerSettings.EnemiesNeededNearFlagToBlockSpawning then
						break;
					end
				end
			end
		end
	end

	Tool:SetAttribute("SpawnsBlocked", not Tool:GetAttribute("UnderCapture") and nearbyEnemies == PlayerSettings.EnemiesNeededNearFlagToBlockSpawning);
	BodyAttach.ContestedGui.Enabled = not Tool:GetAttribute("UnderCapture") and nearbyEnemies == PlayerSettings.EnemiesNeededNearFlagToBlockSpawning;
end
local function GetOppositeTeamColor(team)
	return team == Teams.Team1 and Teams.Team2.TeamColor or Teams.Team1.TeamColor;
end
local function GetOppositeTeamName(teamName)
	return teamName == "Team1" and "Team2" or "Team1";
end
local function DropFlag()
	if not Tool:GetAttribute("Captured") then
		if not Tool:GetAttribute("Dropped") then
			Tool:SetAttribute("Dropped", true);

			local lostFlag = DroppedFlag:Clone();
			lostFlag:SetAttribute("LastTeamName", Tool:GetAttribute("LastTeamName") == "" and Player.Team.Name or Tool:GetAttribute("LastTeamName"));
			lostFlag:SetAttribute("LastOwnerName", Tool:GetAttribute("LastOwnerName") == "" and Player.Name or Tool:GetAttribute("LastOwnerName"));
			lostFlag:SetAttribute("LastLineID", Tool:GetAttribute("LastLineID") == 0 and Player:GetAttribute("LineID") or Tool:GetAttribute("LastLineID"));
			lostFlag:SetAttribute("LastCustomFlag", Tool:GetAttribute("LastCustomFlag") == "" and Player:GetAttribute("CustomFlag") or Tool:GetAttribute("LastCustomFlag"));

			if lostFlag:GetAttribute("LastOwnerName") == Player.Name then
				lostFlag:SetAttribute("LastCustomFlag", Player:GetAttribute("CustomFlag"));
			end
			for each, flagPiece in pairs(lostFlag.FlagPieces:GetChildren()) do
				flagPiece.BrickColor = Player.TeamColor;
				flagPiece.TextureID = "rbxassetid://"..lostFlag:GetAttribute("LastCustomFlag");
			end

			lostFlag:SetPrimaryPartCFrame(Torso.CFrame * CFrame.new(0, -2, 0));
			lostFlag.Parent = workspace.Flags;
		end

		Humanoid:UnequipTools();
		repeat task.wait(0.1); until Tool.Parent == Player.Backpack;
		Tool:Destroy();
	end
end

-- Animation Functions --
local function CreateAnimationTracks()
	if not Character:IsDescendantOf(workspace) then
		repeat task.wait(); until Character:IsDescendantOf(workspace);
	end
	AnimationObjects, AnimationTracks = ServerTechFunctions:CreateAnimationTracks(Animations, Humanoid);

	for each, animationTrack in pairs(AnimationTracks) do
		animationTrack.KeyframeReached:Connect(function(keyframeName)
			if string.sub(keyframeName, 1, 2) == "[[" then
				Settings.BodyStance = keyframeName;
			else
				Settings.ToolStance = keyframeName;
			end
		end)
		animationTrack:GetMarkerReachedSignal("PlaySound"):Connect(function(soundNames)
			ServerTechFunctions:PlaySound(soundNames, Sounds, BodyAttach);
		end)
		animationTrack:GetMarkerReachedSignal("Melee"):Connect(function(status)
			if status == "enabled" then
				Settings.MeleeActive = true;
				while Settings.MeleeActive do
					Settings.MeleeActive = ServerTechFunctions:FindTargetToMelee(Tool.Name, ToolHitbox, Player, Character, Head, CharacterHitbox, Settings.MeleeStabDamage, Settings.MeleeStabStructureDamage, Settings.MeleeBashDamage, Settings.MeleeBashStructureDamage, Settings.ToolStance, Settings.MaximumMeleeAngle, Sounds, BodyAttach);
					task.wait(0.1);
				end
			elseif status == "disabled" then
				Settings.MeleeActive = false;
			end
		end)
		animationTrack:GetMarkerReachedSignal("MeleeAiming"):Connect(function(status)
			if status == "enabled" then
				Tool:SetAttribute("MeleeAiming", true);
			elseif status == "disabled" then
				Tool:SetAttribute("MeleeAiming", false);
			end
		end)
	end
end

-- Weapon Events --
Tool:GetAttributeChangedSignal("Captured"):Connect(function()
	if Tool:GetAttribute("Captured") then
		if ReplicatedStorage:GetAttribute("BattleStarted") then
			local newTickets = math.clamp(ReplicatedStorage:GetAttribute(Player.Team.Name.."Tickets") + PlayerSettings.TicketBonusForFlagCapture, 0, math.huge);
			ReplicatedStorage:SetAttribute(Player.Team.Name.."Tickets", newTickets);
			EventToClient:FireAllClients("NotifyCapture", {ReplicatedStorage:GetAttribute(Player.Team.Name.."Name"), ReplicatedStorage:GetAttribute(GetOppositeTeamName(Player.Team.Name).."Name")});
		end
		Player:SetAttribute("Flags", Player:GetAttribute("Flags") + 1);
		Torso:SetAttribute("TeamColor", Player.Team.TeamColor);
		CommonFunctions:AwardBadge(Player, 3597494177104764, false);

		Humanoid:UnequipTools();
		repeat task.wait(0.1); until Tool.Parent == Player.Backpack;
		Tool:Destroy();
	end
end)
Tool:GetAttributeChangedSignal("UnderCapture"):Connect(function()
	if Tool:GetAttribute("UnderCapture") then
		BodyAttach.CapturingGui.Enabled = true;

		local timeUnderCapture = -1
		while Tool:GetAttribute("UnderCapture") do
			timeUnderCapture += 1;
			if timeUnderCapture == PlayerSettings.TimeToCaptureFlag then
				Tool:SetAttribute("Captured", true);
			end
			task.wait(1);
		end
	end
end)
Tool.AncestryChanged:Connect(function()
	if Tool.Parent == Player.Backpack and EverEquipped then
		Settings.BodyStance = "[[I]] Stood";
		Settings.ToolStance = "[I] Unequipped";
		Settings.MeleeActive = false;
		Settings.MeleePlaying = false;

		Player:SetAttribute("TargetWalkSpeed", StarterPlayer.CharacterWalkSpeed);
		RootJoint.C0 = CFrame.new(0, 0, 0) * CrouchAngle;
		Tool6D:SetAttribute("ActiveTool6D", false);

		Tool:SetAttribute("MeleeAiming", false);
		Tool:SetAttribute("MeleeStance", "Bottom");
		Tool:SetAttribute("Mouse1Held", false);
		Tool:SetAttribute("Mouse2Held", false);

		ServerTechFunctions:DeleteSound("Breeze", BodyAttach);

		DropFlag();
	end
end)
ToolEvent.OnServerEvent:Connect(function(player, dataTable)
	if player == Player and typeof(dataTable) == "table" and dataTable[1] and dataTable[2] and typeof(dataTable[1]) == "Vector3" then
		if Humanoid.Health > 0 then
			if typeof(dataTable[2]) == "string" then
				if dataTable[2] == "Equip" then
					if Settings.ToolStance == "[I] Unequipped" then
						EverEquipped = true;
						Tool6D.Part0 = Torso;
						Tool6D.Part1 = BodyAttach;
						Tool6D:SetAttribute("ActiveTool6D", true);
						ServerTechFunctions:PlaySound("Breeze", Sounds, BodyAttach);
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Equip"], AnimationTracks["[I] Carried Arms"], "[", AnimationTracks, AnimationObjects);
						if Tool:GetAttribute("LastTeamName") ~= "" and Tool:GetAttribute("LastTeamName") ~= Player.Team.Name then
							Tool:SetAttribute("UnderCapture", true);
							Torso:SetAttribute("TeamColor", GetOppositeTeamColor());
						end
					end
				elseif dataTable[2] == "AimMelee" or dataTable[2] == "BlockMelee" then
					if dataTable[3] and typeof(dataTable[3]) == "string" then
						if dataTable[3] == "Top" or dataTable[3] == "Bottom" or dataTable[3] == "Left" or dataTable[3] == "Right" then
							if string.sub(Settings.ToolStance, 1, 3) == "[I]" and not Settings.MeleePlaying then
								Settings.MeleePlaying = true;

								if dataTable[2] == "AimMelee" then
									ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Melee "..dataTable[3].." Pull"], AnimationTracks["[I] Melee "..dataTable[3].." Pulled"], "[", AnimationTracks, AnimationObjects);
									task.wait(AnimationObjects["[M] Melee "..dataTable[3].." Pull"]:GetAttribute("AnimationSpeed") - 0.1);
									while Tool:GetAttribute("Mouse1Held") do
										task.wait();
									end
									if Settings.MeleePlaying then
										ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Melee "..dataTable[3].." Push"], AnimationTracks["[I] Meleed Arms"], "[", AnimationTracks, AnimationObjects);
									end
								elseif dataTable[2] == "BlockMelee" then
									ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Melee "..dataTable[3].." Block"], AnimationTracks["[I] Melee "..dataTable[3].." Blocked"], "[", AnimationTracks, AnimationObjects);
									task.wait(AnimationObjects["[M] Melee "..dataTable[3].." Block"]:GetAttribute("AnimationSpeed") - 0.1);
									while Tool:GetAttribute("Mouse2Held") do
										task.wait();
									end
									if Settings.MeleePlaying then
										ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Melee "..dataTable[3].." Unblock"], AnimationTracks["[I] Meleed Arms"], "[", AnimationTracks, AnimationObjects);
									end
								end

								Settings.MeleePlaying = false;
							end
						end
					end
				elseif dataTable[2] == "Mouse1Held" then
					if typeof(dataTable[3]) == "boolean" then
						Tool:SetAttribute("Mouse1Held", dataTable[3]);
					end
				elseif dataTable[2] == "Mouse2Held" then
					if typeof(dataTable[3]) == "boolean" then
						Tool:SetAttribute("Mouse2Held", dataTable[3]);
					end
				end
			elseif typeof(dataTable[2]) == "EnumItem" and typeof(dataTable[3]) == "EnumItem" then
				if dataTable[3] == Settings.OrderArmsKey then
					if Settings.ToolStance == "[I] Carried Arms" then
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Order Arms"], AnimationTracks["[I] Ordered Arms"], "[", AnimationTracks, AnimationObjects);
					elseif Settings.ToolStance == "[I] Ordered Arms" then
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Unorder Arms"], AnimationTracks["[I] Carried Arms"], "[", AnimationTracks, AnimationObjects);
					end
				elseif dataTable[3] == Settings.CrouchKey then
					if Settings.BodyStance == "[[I]] Stood" then
						TweenService:Create(RootJoint, CrouchTweenInfo, {C0 = CFrame.new(0, -1.161, 0) * CrouchAngle}):Play();
						ServerTechFunctions:PlayAnimations(AnimationTracks["[[M]] Crouch"], AnimationTracks["[[I]] Crouched"], "[[", AnimationTracks, AnimationObjects);
					elseif Settings.BodyStance == "[[I]] Crouched" then
						TweenService:Create(RootJoint, CrouchTweenInfo, {C0 = CFrame.new(0, 0, 0) * CrouchAngle}):Play();
						ServerTechFunctions:PlayAnimations(AnimationTracks["[[M]] Uncrouch"], AnimationTracks["[[I]] Stood"], "[[", AnimationTracks, AnimationObjects);
					end
				elseif dataTable[3] == Settings.MeleeArmsKey then
					if Settings.ToolStance == "[I] Carried Arms" then
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Melee Arms"], AnimationTracks["[I] Meleed Arms"], "[", AnimationTracks, AnimationObjects);
					elseif Settings.ToolStance == "[I] Meleed Arms" then
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Unmelee Arms"], AnimationTracks["[I] Carried Arms"], "[", AnimationTracks, AnimationObjects);
					end
				elseif dataTable[3] == Settings.RaiseArmsKey then
					if Settings.ToolStance == "[I] Carried Arms" then
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Raise Arms"], AnimationTracks["[I] Raised Arms"], "[", AnimationTracks, AnimationObjects);
					elseif Settings.ToolStance == "[I] Raised Arms" then
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Unraise Arms"], AnimationTracks["[I] Carried Arms"], "[", AnimationTracks, AnimationObjects);
					end
				elseif dataTable[3] == Settings.SaluteArmsKey then
					if Settings.ToolStance == "[I] Carried Arms" then
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Salute Arms"], AnimationTracks["[I] Saluted Arms"], "[", AnimationTracks, AnimationObjects);
					elseif Settings.ToolStance == "[I] Saluted Arms" then
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Unsalute Arms"], AnimationTracks["[I] Carried Arms"], "[", AnimationTracks, AnimationObjects);
					end
				end
			end
		end
	end
end)

