-- Initial Function --
local function Initialize()
	debug.setmemorycategory("Script_FlagServer");

	if Torso:FindFirstChild("Flag6D") then
		Torso.Flag6D:Destroy();
	end
	Tool6D:SetAttribute("ActiveTool6D", false);
	Tool6D.Name = "Flag6D";
	Tool6D.Parent = Torso;

	Tool:SetAttribute("LastLineID", Tool:GetAttribute("LastLineID") == 0 and Player:GetAttribute("LineID") or Tool:GetAttribute("LastLineID"));

	for each, flagPiece in pairs(FlagPieces:GetChildren()) do
		flagPiece.BrickColor = Player.TeamColor;
		flagPiece.TextureID = Tool:GetAttribute("LastCustomFlag") == "" and "rbxassetid://"..Player:GetAttribute("CustomFlag") or "rbxassetid://"..Tool:GetAttribute("LastCustomFlag");
	end

	CreateAnimationTracks();

	Settings.Initialized = true;
end
Initialize();

