-- Local Functions --
local function PassedAimCooldown()
	if os.clock() - AimClock > 0.1 then
		AimClock = os.clock();
		return true;
	end
end

-- Damage Functions --
local function ShootProjectile(dataTable)
	local shootingParams = ServerTechFunctions:GetShootingParams(Player);
	if RNG:NextInteger(0, 100) <= Settings.AmmoChanceToInstaKill then
		ServerTechFunctions:ShootProjectile(Character, Player, shootingParams, ToolFolder, dataTable[1], Settings.WeaponMinimumSpread, Settings.WeaponMaximumSpread, Settings.WeaponMaximumRange, Settings.MaximumAimAngle, math.huge, Settings.AmmoStructureDamage, Settings.DebugEnabled, Settings.VisualizeRaycasts, Settings.RaycastsExpire, Settings.WeaponInstaKillRange);
	else
		ServerTechFunctions:ShootProjectile(Character, Player, shootingParams, ToolFolder, dataTable[1], Settings.WeaponMinimumSpread, Settings.WeaponMaximumSpread, Settings.WeaponMaximumRange, Settings.MaximumAimAngle, Settings.AmmoDamage, Settings.AmmoStructureDamage, Settings.DebugEnabled, Settings.VisualizeRaycasts, Settings.RaycastsExpire, Settings.WeaponInstaKillRange);
	end
end

-- Animation Functions --
local function CreateAnimationTracks()
	if not Character:IsDescendantOf(workspace) then
		repeat task.wait(0.1); until Character:IsDescendantOf(workspace);
	end
	AnimationObjects, AnimationTracks = ServerTechFunctions:CreateAnimationTracks(Animations, Humanoid);

	for each, animationTrack in pairs(AnimationTracks) do
		animationTrack.KeyframeReached:Connect(function(keyframeName)
			if string.sub(keyframeName, 1, 2) == "[[" then
				Settings.BodyStance = keyframeName;
			else
				Settings.ToolStance = keyframeName;
			end
		end)
		animationTrack:GetMarkerReachedSignal("TTV"):Connect(function()
			local bayonetVisible = Settings.BayonetEquipped and Settings.BayonetAvailable;
			ServerTechFunctions:ToggleToolVisibility(true, ToolFolder, Settings.BayonetEquipped, Settings.BayonetAvailable);
			ServerTechFunctions:ToggleHolsterDisplay(false, Character, Tool, bayonetVisible);
		end)
		animationTrack:GetMarkerReachedSignal("PlaySound"):Connect(function(soundNames)
			ServerTechFunctions:PlaySound(soundNames, Sounds, BodyAttach);
		end)
		animationTrack:GetMarkerReachedSignal("Reloaded"):Connect(function()
			Settings.AmmoInReserve -= 1;
			Player:SetAttribute(Tool.Name.."Loaded", true)
		end)
		animationTrack:GetMarkerReachedSignal("Bayonet"):Connect(function(status)
			if status == "enabled" then
				Settings.MeleeActive = true;
				while Settings.MeleeActive do
					Settings.MeleeActive = ServerTechFunctions:FindTargetToMelee(Tool.Name, ToolHitbox, Player, Character, Head, CharacterHitbox, Settings.MeleeStabDamage, Settings.MeleeStabStructureDamage, Settings.MeleeBashDamage, Settings.MeleeBashStructureDamage, Settings.ToolStance, Settings.MaximumMeleeAngle, Sounds, BodyAttach);
					task.wait(0.1);
				end
			elseif status == "disabled" then
				Settings.MeleeActive = false;
			end
		end)
		animationTrack:GetMarkerReachedSignal("BayonetVisible"):Connect(function(transparency)
			Bayonet.Transparency = tonumber(transparency);
		end)
		animationTrack:GetMarkerReachedSignal("CartridgeVisible"):Connect(function(transparency)
			Cartridge.Transparency = tonumber(transparency);
		end)
		animationTrack:GetMarkerReachedSignal("Aiming"):Connect(function(status)
			if status == "enabled" then
				Tool:SetAttribute("Aiming", true);
			elseif status == "disabled" then
				Tool:SetAttribute("Aiming", false);
				Tool:SetAttribute("Fired", false);
			end
		end)
		animationTrack:GetMarkerReachedSignal("BayonetAiming"):Connect(function(status)
			if status == "enabled" then
				Tool:SetAttribute("MeleeAiming", true);
			elseif status == "disabled" then
				Tool:SetAttribute("MeleeAiming", false);
			end
		end)
		animationTrack:GetMarkerReachedSignal("BayonetEquipped"):Connect(function(status)
			if status == "enabled" then
				Settings.BayonetEquipped = true;
			elseif status == "disabled" then
				Settings.BayonetEquipped = false;
			end
		end)
		animationTrack:GetMarkerReachedSignal("Fire"):Connect(function(status)
			EventToClient:FireAllClients("FireParticles", {status, FireParts, 0.1});
		end)
	end
end

