		Tool:SetAttribute("Mouse1Held", false);
		Tool:SetAttribute("Mouse2Held", false);

		ServerTechFunctions:ToggleToolVisibility(false, ToolFolder);
		ServerTechFunctions:ToggleHolsterDisplay(true, Character, Tool, bayonetVisible);
