ToolEvent.OnServerEvent:Connect(function(player, dataTable)
	if Humanoid.Health > 0 and player == Player and typeof(dataTable) == "table" and dataTable[1] and dataTable[2] and typeof(dataTable[1]) == "Vector3" then
		if typeof(dataTable[2]) == "string" then
			if dataTable[2] == "Equip" then
				if Settings.ToolStance == "[I] Unequipped" then
					Tool6D.Part0 = Torso;
					Tool6D.Part1 = BodyAttach;
					Tool6D:SetAttribute("ActiveTool6D", true);
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Equip"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
				end
			elseif dataTable[2] == "ReplicateAim" and PassedAimCooldown() then
				SharedTechFunctions:AimPlayer(Player, dataTable[1], Tool);
			elseif dataTable[2] == "AimMelee" or dataTable[2] == "BlockMelee" and Settings.BayonetEquipped then
				if dataTable[3] and typeof(dataTable[3]) == "string" then
					if dataTable[3] == "Top" or dataTable[3] == "Bottom" or dataTable[3] == "Left" or dataTable[3] == "Right" then
						if string.sub(Settings.ToolStance, 1, 3) == "[I]" and not Settings.MeleePlaying then
							Settings.MeleePlaying = true;

							if dataTable[2] == "AimMelee" then
								ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Bayonet "..dataTable[3].." Pull"], AnimationTracks["[I] Bayonet "..dataTable[3].." Pulled"], "[", AnimationTracks, AnimationObjects);
								task.wait(AnimationObjects["[M] Bayonet "..dataTable[3].." Pull"]:GetAttribute("AnimationSpeed") - 0.1);
								while Tool:GetAttribute("Mouse1Held") do
									task.wait();
								end
								if Settings.MeleePlaying then
									ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Bayonet "..dataTable[3].." Push"], AnimationTracks["[I] Bayoneted Arms"], "[", AnimationTracks, AnimationObjects);
								end
							elseif dataTable[2] == "BlockMelee" then
								ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Bayonet "..dataTable[3].." Block"], AnimationTracks["[I] Bayonet "..dataTable[3].." Blocked"], "[", AnimationTracks, AnimationObjects);
								task.wait(AnimationObjects["[M] Bayonet "..dataTable[3].." Block"]:GetAttribute("AnimationSpeed") - 0.1);
								while Tool:GetAttribute("Mouse2Held") do
									task.wait();
								end
								if Settings.MeleePlaying then
									ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Bayonet "..dataTable[3].." Unblock"], AnimationTracks["[I] Bayoneted Arms"], "[", AnimationTracks, AnimationObjects);
								end
							end

							Settings.MeleePlaying = false;
						end
					end
				end
			elseif dataTable[2] == "Mouse1Held" then
				if typeof(dataTable[3]) == "boolean" then
					Tool:SetAttribute("Mouse1Held", dataTable[3]);
				end
			elseif dataTable[2] == "Mouse2Held" then
				if typeof(dataTable[3]) == "boolean" then
					Tool:SetAttribute("Mouse2Held", dataTable[3]);
				end
			end
		elseif typeof(dataTable[2]) == "EnumItem" and typeof(dataTable[3]) == "EnumItem" then
			if dataTable[2] == Enum.UserInputType.MouseButton1 then
				if Settings.ToolStance == "[I] Shouldered Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Make Ready"], AnimationTracks["[I] Made Ready"], "[", AnimationTracks, AnimationObjects);
				elseif Settings.ToolStance == "[I] Advanced Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] MakeReadyFromAdvanced"], AnimationTracks["[I] Made Ready"], "[", AnimationTracks, AnimationObjects);
				elseif Settings.ToolStance == "[I] Ported Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] MakeReadyFromPorted"], AnimationTracks["[I] Made Ready"], "[", AnimationTracks, AnimationObjects);
				elseif Settings.ToolStance == "[I] Made Ready" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Unmake Ready"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
				elseif Settings.ToolStance == "[I] Presented" then
					Tool:SetAttribute("Fired", true);
					if Player:GetAttribute(Tool.Name.."Loaded") then
						Player:SetAttribute(Tool.Name.."Loaded", false);
						EventToClient:FireClient(player, "CameraShake");
						if Settings.VisualizeRaycasts and Settings.DebugEnabled then
							for i = 1, Settings.NumberOfRaycastsToVisualize do
								ShootProjectile(dataTable);
							end
						else
							ShootProjectile(dataTable);
						end
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Fire"], AnimationTracks["[I] Fired"], "[", AnimationTracks, AnimationObjects);
					else
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] FireFail"], AnimationTracks["[I] Fired"], "[", AnimationTracks, AnimationObjects);
					end
				end
			elseif dataTable[3] == Settings.PresentKey then
				if Settings.ToolStance == "[I] Made Ready" then
					Tool:SetAttribute("Aiming", true);
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Present"], AnimationTracks["[I] Presented"], "[", AnimationTracks, AnimationObjects);
				elseif Settings.ToolStance == "[I] Presented" then
					Tool:SetAttribute("Aiming", false);
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Unpresent"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
				elseif Settings.ToolStance == "[I] Fired" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Unfire"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
				elseif Settings.ToolStance == "[I] Bayoneted Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] MakeReadyFromBayonetArms"], AnimationTracks["[I] Made Ready"], "[", AnimationTracks, AnimationObjects);
				end
			elseif dataTable[3] == Settings.ReloadKey then
				if not Player:GetAttribute(Tool.Name.."Loaded") and Settings.AmmoInReserve - 1 >= 0 then
					if Settings.ToolStance == "[I] Fired" then
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Reload"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
					elseif Settings.ToolStance == "[I] Shouldered Arms" then
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] ReloadFromShoulderArms"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
					elseif Settings.ToolStance == "[I] Bayoneted Arms" then
						ServerTechFunctions:PlayAnimations(AnimationTracks["[M] ReloadFromBayonetArms"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
					end
				end
			elseif dataTable[3] == Settings.FixBayonetKey and Settings.BayonetAvailable then
				if Settings.ToolStance == "[I] Shouldered Arms" and not Settings.BayonetEquipped then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Fix Bayonet"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
				elseif Settings.ToolStance == "[I] Shouldered Arms" and Settings.BayonetEquipped then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Unfix Bayonet"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
				end
			elseif dataTable[3] == Settings.AdvanceArmsKey then
				if Settings.ToolStance == "[I] Shouldered Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Advance Arms"], AnimationTracks["[I] Advanced Arms"], "[", AnimationTracks, AnimationObjects);
				elseif Settings.ToolStance == "[I] Advanced Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Unadvance Arms"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
				end
			elseif dataTable[3] == Settings.OrderArmsKey then
				if Settings.ToolStance == "[I] Shouldered Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Order Arms"], AnimationTracks["[I] Ordered Arms"], "[", AnimationTracks, AnimationObjects);
				elseif Settings.ToolStance == "[I] Ordered Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Unorder Arms"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
				end
			elseif dataTable[3] == Settings.PortArmsKey then
				if Settings.ToolStance == "[I] Shouldered Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Port Arms"], AnimationTracks["[I] Ported Arms"], "[", AnimationTracks, AnimationObjects);
				elseif Settings.ToolStance == "[I] Ported Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Unport Arms"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
				end
			elseif dataTable[3] == Settings.TrailArmsKey then
				if Settings.ToolStance == "[I] Shouldered Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Trail Arms"], AnimationTracks["[I] Trailed Arms"], "[", AnimationTracks, AnimationObjects);
				elseif Settings.ToolStance == "[I] Trailed Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Untrail Arms"], AnimationTracks["[I] Shouldered Arms"], "[", AnimationTracks, AnimationObjects);
				end
			elseif dataTable[3] == Settings.SupportArmsKey then
				if Settings.ToolStance == "[I] Shouldered Arms" then
					ServerTechFunctions:PlayAnimations(AnimationTracks["[M] Support Arms"], AnimationTracks["[I] Supported Arms"], "[", AnimationTracks, AnimationObjects);
