local Humanoid = Character:WaitForChild("Humanoid");

-- CharacterIsInLine Variables --
local nearBoxSize = Vector3.new(10, 5, 5);
local farBoxSize = Vector3.new(24, 5, 5);
local rankBoxSize = Vector3.new(7, 5, 7);
local boxParams = OverlapParams.new();
boxParams.FilterType = Enum.RaycastFilterType.Exclude;
boxParams.FilterDescendantsInstances = {workspace.Bots, workspace.Map, workspace.Structures, workspace.Targets, workspace.Visuals};

-- Modules --
local Modules = ReplicatedStorage:WaitForChild("Modules");
local PlayerSettings = require(Modules.PlayerSettings);

-- Functions --
local function TorsoIsValid(potentialTorso)
	if potentialTorso.Name ~= "Torso" or potentialTorso == Torso then
		return false;
	end
	if potentialTorso.Parent.Humanoid.Health <= 0 then
		return false;
	end
	if (potentialTorso.Position - Torso.Position).Magnitude <= PlayerSettings.DistanceToDisqualifyTeammate then
		return false;
	end
	local player = Players:GetPlayerFromCharacter(potentialTorso.Parent);
	if player and player.Team ~= Player.Team then
		return false;
	end
	return true;
end
local function CharacterIsNearFlag()
	for each, character in pairs(workspace:GetChildren()) do
		local player = Players:GetPlayerFromCharacter(character);
		if player and player.Team == Player.Team then
			local flagTool = character:FindFirstChildOfClass("Tool");
			if flagTool and flagTool.Name == "Flag" and flagTool.Flag:FindFirstChild("BodyAttach") then
				if (Torso.Position - flagTool.Flag.BodyAttach.Position).Magnitude <= PlayerSettings.MoraleDistanceForFlag then
					return true;
				end
			end
		end
	end
	for each, structure in pairs(workspace.Structures:GetChildren()) do
		if structure.Name == "Fort" and structure:GetAttribute("TeamColor") == Player.TeamColor then
			if (Torso.Position - structure.PrimaryPart.Position).Magnitude <= PlayerSettings.MoraleDistanceForFlag then
				return true;
			end
		end
	end
end
local function CharacterIsNearSpawn(spawnType)
	if ReplicatedStorage:GetAttribute("BattleStarted") then
		return false;
	end
	for each, spawnPad in pairs(Map.Spawns:GetChildren()) do
		local spawnPadTeamColor = spawnPad:GetAttribute("TeamColor");
		if (spawnPadTeamColor == Player.TeamColor and spawnType == "Team") or (spawnPadTeamColor ~= Player.TeamColor and spawnType == "Enemy") then
			if (Torso.Position - spawnPad.Position).Magnitude <= PlayerSettings.MoraleDistanceForSpawn then
				return true;
			end
		end
	end
end
local function CharacterIsNearGamerOkami()
	for each, character in pairs(workspace:GetChildren()) do
		local player = Players:GetPlayerFromCharacter(character);
		local torso = character:FindFirstChild("Torso");
		local humanoid = character:FindFirstChild("Humanoid");
		if player and torso and humanoid then
			if player.Name == "GamerOkami" and character.Humanoid.Health > 0 and player.Team == Player.Team then
				if (Torso.Position - torso.Position).Magnitude <= PlayerSettings.MoraleDistanceForGamerOkami then
					return true;
				end
			end
		end
	end
end
local function CharacterIsInGroup()
	local nearCharacters = 0;
	for each, character in pairs(workspace:GetChildren()) do
		local torso = character:FindFirstChild("Torso");
		local humanoid = character:FindFirstChild("Humanoid");
		if torso and humanoid then
			if TorsoIsValid(torso) then
				if (Torso.Position - torso.Position).Magnitude <= PlayerSettings.MoraleDistanceForGroup then
					nearCharacters += 1;
					if nearCharacters == PlayerSettings.TeammatesNeededForInGroup then
						return true;
					end
				end
			end
		end
	end
end
local function CharacterIsInLine()
	local farCharacters = {};
	local nearCharacters = {};
	local frontCharacters = {};
	local inLine = false;
	local inRank = false;

	local farPartsFound = workspace:GetPartBoundsInBox(Torso.CFrame, farBoxSize, boxParams);
	if farPartsFound then
		for each, potentialTorso in pairs(farPartsFound) do
			if TorsoIsValid(potentialTorso) then
				table.insert(farCharacters, potentialTorso.Parent);
				if #farCharacters == PlayerSettings.TeammatesNeededInFarLine then
					inLine = true;
					break;
				end
			end
		end
	end

	if not inLine and #farCharacters >= PlayerSettings.TeammatesNeededInFarLineToQualifyForCloseLine then
		local nearPartsFound = workspace:GetPartBoundsInBox(Torso.CFrame, nearBoxSize, boxParams);
		if nearPartsFound then
			for each, potentialTorso in pairs(nearPartsFound) do
				if TorsoIsValid(potentialTorso) then
					table.insert(nearCharacters, potentialTorso.Parent);
					if #nearCharacters == PlayerSettings.TeammatesNeededInCloseLine then
						inLine = true;
						break;
					end
				end
			end
		end
	end

	if inLine then
		local frontPartsFound = workspace:GetPartBoundsInBox(Torso.CFrame, rankBoxSize, boxParams);
		if frontPartsFound then
			for each, potentialTorso in pairs(frontPartsFound) do
				if TorsoIsValid(potentialTorso) then
					if not table.find(nearCharacters, potentialTorso.Parent) then
						table.insert(frontCharacters, potentialTorso.Parent);
						if #frontCharacters == PlayerSettings.TeammatesNeededInRank then
							inRank = true;
							break;
						end
					end
				end
			end
		end
	end

	return inLine, inRank;
end
local function UpdatePlayerMorale()
	local morale = Player:GetAttribute("Morale");
	local nearFlag = CharacterIsNearFlag();
	local nearTeamSpawn = CharacterIsNearSpawn("Team");
	local nearEnemySpawn = CharacterIsNearSpawn("Enemy");
	local nearGamerOkami = CharacterIsNearGamerOkami();
	local inLine, inRank = CharacterIsInLine();
	local inGroup = not inLine and CharacterIsInGroup();
	local isBleeding = Character:GetAttribute("Bleeding");

	morale = morale + (((nearFlag and PlayerSettings.MoraleFromNearFlag) or PlayerSettings.MoraleFromFarFlag) * PlayerSettings.UpdateFrequency);
	morale = morale + (((nearTeamSpawn and PlayerSettings.MoraleFromNearTeamSpawn) or PlayerSettings.MoraleFromFarTeamSpawn) * PlayerSettings.UpdateFrequency);
	morale = morale + (((nearEnemySpawn and PlayerSettings.MoraleFromNearEnemySpawn) or PlayerSettings.MoraleFromFarEnemySpawn) * PlayerSettings.UpdateFrequency);
	morale = morale + (((nearGamerOkami and PlayerSettings.MoraleFromNearGamerOkami) or PlayerSettings.MoraleFromFarGamerOkami) * PlayerSettings.UpdateFrequency);
	morale = morale + (((inRank and PlayerSettings.MoraleFromInRank) or PlayerSettings.MoraleFromNoRank) * PlayerSettings.UpdateFrequency);
	morale = morale + (((not inRank and inLine and PlayerSettings.MoraleFromInLine) or PlayerSettings.MoraleFromNoLine) * PlayerSettings.UpdateFrequency);
	morale = morale + (((inGroup and PlayerSettings.MoraleFromInGroup) or PlayerSettings.MoraleFromNoGroup) * PlayerSettings.UpdateFrequency);
	morale = morale + (((isBleeding and PlayerSettings.MoraleFromBleed) or 0) * PlayerSettings.UpdateFrequency);

	EventToClient:FireClient(Player, "UpdateMain", {"Flag", nearFlag and Humanoid.Health > 0});
	EventToClient:FireClient(Player, "UpdateMain", {"Spawning", nearTeamSpawn and Humanoid.Health > 0});
	EventToClient:FireClient(Player, "UpdateMain", {"Trapping", nearEnemySpawn and Humanoid.Health > 0});
	EventToClient:FireClient(Player, "UpdateMain", {"Rank", inRank and Humanoid.Health > 0});
	EventToClient:FireClient(Player, "UpdateMain", {"Line", not inRank and inLine and Humanoid.Health > 0});
	EventToClient:FireClient(Player, "UpdateMain", {"Group", inGroup and Humanoid.Health > 0});
	EventToClient:FireClient(Player, "UpdateMain", {"GamerOkami", nearGamerOkami and Humanoid.Health > 0});
	EventToClient:FireClient(Player, "UpdateMain", {"Bleeding", isBleeding and Humanoid.Health > 0});
	EventToClient:FireClient(Player, "UpdateMain", {"Cavalry", false and Humanoid.Health > 0});
	EventToClient:FireClient(Player, "UpdateMain", {"Chanting", false and Humanoid.Health > 0});
	EventToClient:FireClient(Player, "UpdateMain", {"Music", false and Humanoid.Health > 0});

	if Player:GetAttribute("MoraleGod") then
		morale = PlayerSettings.MoraleMaximum;
	elseif Humanoid.Health <= 0 then
		morale = 0;
	end

	morale = math.clamp(morale, 0, PlayerSettings.MoraleMaximum);
	if Humanoid.Health > 0 and morale <= PlayerSettings.MoraleThresholdForTicketPenalty and ReplicatedStorage:GetAttribute("BattleStarted") then
		CyclesAtLowMorale += 1;
		if CyclesAtLowMorale * PlayerSettings.UpdateFrequency >= 1 then
			local newTickets = math.clamp(ReplicatedStorage:GetAttribute(Player.Team.Name.."Tickets") + PlayerSettings.TicketPenaltyForLowMorale, 0, math.huge);
			ReplicatedStorage:SetAttribute(Player.Team.Name.."Tickets", newTickets);
			CyclesAtLowMorale = 0;
		end
	else
		CyclesAtLowMorale = 0;
	end

	Player:SetAttribute("Morale", morale);
	Character:SetAttribute("InLine", not inRank and inLine);
	Character:SetAttribute("InRank", inRank);
end

-- Player Events --
Humanoid.Died:Connect(function()
	if ReplicatedStorage:GetAttribute("BattleStarted") and Character:GetAttribute("Damaged") then
		local inLine, inRank = CharacterIsInLine();
		local inGroup = CharacterIsInGroup() and not inLine;
		if inLine or inRank then
			local newTickets = math.clamp(ReplicatedStorage:GetAttribute(Player.Team.Name.."Tickets") + PlayerSettings.TicketPenaltyForLineCasualty, 0, math.huge);
			ReplicatedStorage:SetAttribute(Player.Team.Name.."Tickets", newTickets);
		elseif inGroup then
			local newTickets = math.clamp(ReplicatedStorage:GetAttribute(Player.Team.Name.."Tickets") + PlayerSettings.TicketPenaltyForGroupCasualty, 0, math.huge);
			ReplicatedStorage:SetAttribute(Player.Team.Name.."Tickets", newTickets);
		else
			local newTickets = math.clamp(ReplicatedStorage:GetAttribute(Player.Team.Name.."Tickets") + PlayerSettings.TicketPenaltyForRamboCasualty, 0, math.huge);
			ReplicatedStorage:SetAttribute(Player.Team.Name.."Tickets", newTickets);
		end
	end
end)

-- Initialize Function --
local function Initialize()
	while true do
		if Player:GetAttribute("Spawned") then
			UpdatePlayerMorale();
		elseif Player:GetAttribute("MoraleGod") then
			Player:SetAttribute("Morale", PlayerSettings.MoraleMaximum);
		end
		task.wait(PlayerSettings.UpdateFrequency);
	end
end
Initialize();
